VALUES ('doc-09-mitre-attack-p0-21436', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-19T14:33:04.202Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GrimAgent](https://attack.mitre.org/software/S0632) uses the last 64 bytes of the binary to compute a mutex name. If the generated name is invalid, it will default to the generic `mymutex`.(Citation: Group IB GrimAgent July 2021)", "external_references": [{"description": "Priego, A. (2021, July). THE BROTHERS GRIM: THE REVERSING TALE OF GRIMAGENT MALWARE USED BY RYUK. Retrieved September 19, 2024.", "source_name": "Group IB GrimAgent July 2021", "url": "https://www.group-ib.com/blog/grimagent/"}], "id": "relationship--6f145407-cd6b-4e96-957f-a74cd6c84c52", "modified": "2026-04-29T14:23:06.076Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c9b99d03-ff11-4a48-95f0-82660d582c25", "spec_version": "2.1", "target_ref": "attack-pattern--49fca0d2-685d-41eb-8bd4-05451cc3a742", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21436', 0, 91, '09-mitre-attack', 'retrieved', '54C5C753F3C13D63B3206347A106DD526F527454D9BED4A1CFEE1F8FE58F6D37', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
