VALUES ('doc-09-mitre-attack-p0-21468', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-09T20:33:21.135Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[STEADYPULSE](https://attack.mitre.org/software/S1112) can parse web requests made to a targeted server to determine the next stage of execution.(Citation: Mandiant Pulse Secure Zero-Day April 2021)", "external_references": [{"description": "Perez, D. et al. (2021, April 20). Check Your Pulse: Suspected APT Actors Leverage Authentication Bypass Techniques and Pulse Secure Zero-Day. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Zero-Day April 2021", "url": "https://www.mandiant.com/resources/blog/suspected-apt-actors-leverage-bypass-techniques-pulse-secure-zero-day"}], "id": "relationship--dfccba8d-5ad0-48be-ba81-8080a12da010", "modified": "2026-04-29T14:23:06.230Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ca0fead6-5277-427a-825b-42ff1fbe476e", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21468', 0, 88, '09-mitre-attack', 'retrieved', '91228DC137CD73BE4E4B59181C443853826BF7C5AC3EDACB8F5F7CAED35B446A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
