VALUES ('doc-09-mitre-attack-p0-21470', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T15:10:52.882Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PHASEJAM](https://attack.mitre.org/software/S9014) has modified legitimate components to enable persistence and execution, including inserting a web shell into `getComponent.cgi` and `restAuth.cgi`, modifying `DSUpgrade.pm` to block system upgrades, and overwriting `remotedebug` to execute arbitrary commands when specific parameters are provided.(Citation: Google UNC5221 Ivanti January 2025)", "external_references": [{"description": "John Wolfram, Josh Murchie, Matt Lin, Daniel Ainsworth, Robert Wallace, Dimiter Andonov, Dhanesh Kizhakkinan, Jacob Thompson. (2025, January 8). Ivanti Connect Secure VPN Targeted in New Zero-Day Exploitation. Retrieved April 14, 2026.", "source_name": "Google UNC5221 Ivanti January 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/ivanti-connect-secure-vpn-zero-day"}], "id": "relationship--08057a27-6711-4956-8a27-739ad26a2883", "modified": "2026-04-29T14:23:05.914Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ca3f5123-b853-45ef-83cb-1d1bca22e03f", "spec_version": "2.1", "target_ref": "attack-pattern--960c3c86-1480-4d72-b4e0-8c242e84a5c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21470', 0, 113, '09-mitre-attack', 'retrieved', '2FCFA5685FBA8223F4BFC36BC92E25C02F0FD1EA62A68AE91655E47C27280A02', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
