VALUES ('doc-09-mitre-attack-p0-21482', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T14:49:00.417Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PHASEJAM](https://attack.mitre.org/software/S9014) has used a bash script to modify components on Ivanti Connect Secure appliances and execute files via `/bin/bash`.[1] It has also used the Linux stream editor (`sed`) to execute commands.(Citation: Google UNC5221 Ivanti January 2025)", "external_references": [{"description": "John Wolfram, Josh Murchie, Matt Lin, Daniel Ainsworth, Robert Wallace, Dimiter Andonov, Dhanesh Kizhakkinan, Jacob Thompson. (2025, January 8). Ivanti Connect Secure VPN Targeted in New Zero-Day Exploitation. Retrieved April 14, 2026.", "source_name": "Google UNC5221 Ivanti January 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/ivanti-connect-secure-vpn-zero-day"}], "id": "relationship--e198f9cc-a750-4fb7-a49e-bf440af377e1", "modified": "2026-04-29T14:23:06.233Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ca3f5123-b853-45ef-83cb-1d1bca22e03f", "spec_version": "2.1", "target_ref": "attack-pattern--b63a34e8-0a61-4c97-a23b-bf8a2ed812e2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21482', 0, 107, '09-mitre-attack', 'retrieved', 'A237F3F4D0C4871E4F79AC5BC0A687B2BFEB664058EBB0D67B85BECC0097FA2D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
