VALUES ('doc-09-mitre-attack-p0-21537', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-15T16:50:05.783Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lokibot](https://attack.mitre.org/software/S0447) has demonstrated the ability to steal credentials from multiple applications and data sources including Safari and the Chromium and Mozilla Firefox-based web browsers.(Citation: Infoblox Lokibot January 2019)", "external_references": [{"description": "Hoang, M. (2019, January 31). Malicious Activity Report: Elements of Lokibot Infostealer. Retrieved May 15, 2020.", "source_name": "Infoblox Lokibot January 2019", "url": "https://insights.infoblox.com/threat-intelligence-reports/threat-intelligence--22"}], "id": "relationship--fe69bcdd-8df4-44e3-8994-b46e4d4c8aac", "modified": "2026-04-29T14:23:06.270Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--cb741463-f0fe-42e0-8d45-bc7e8335f5ae", "spec_version": "2.1", "target_ref": "attack-pattern--58a3e6aa-4453-4cc8-a51f-4befe80b31a8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21537', 0, 82, '09-mitre-attack', 'retrieved', '00DF4267A8DFF13974F8A45C0A8904F2AFD23CA28553C24E929F26F57F0BF1A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
