VALUES ('doc-09-mitre-attack-p0-21542', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROCKBOOT](https://attack.mitre.org/software/S0112) is a Master Boot Record (MBR) bootkit that uses the MBR to establish persistence.(Citation: FireEye Bootkits)", "external_references": [{"description": "Andonov, D., et al. (2015, December 7). Thriving Beyond The Operating System: Financial Threat Group Targets Volume Boot Record. Retrieved May 13, 2016.", "source_name": "FireEye Bootkits", "url": "https://www.fireeye.com/blog/threat-research/2015/12/fin1-targets-boot-record.html"}], "id": "relationship--44b56e08-7cd1-442c-8806-c69bb65fd231", "modified": "2026-04-29T14:23:06.019Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--cba78a1c-186f-4112-9e6a-be1839f030f7", "spec_version": "2.1", "target_ref": "attack-pattern--1b7b1806-7746-41a1-a35d-e48dae25ddba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21542', 0, 76, '09-mitre-attack', 'retrieved', '1521113A4F5A195B6F6B1A6A05070958E7756E680EAABB358D0AA50B2CC9A1E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
