VALUES ('doc-09-mitre-attack-p0-21543', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "One variant of [CloudDuke](https://attack.mitre.org/software/S0054) uses HTTP and HTTPS for C2.(Citation: F-Secure The Dukes)", "external_references": [{"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "relationship--41edf1d6-15a7-4da5-9bfd-ebee9d53f71e", "modified": "2026-04-29T14:23:06.015Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--cbf646f1-7db5-4dc6-808b-0094313949df", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21543', 0, 66, '09-mitre-attack', 'retrieved', '69BE7876B4FDDC26A76F632F0DEF5A21E0AC887E5C3708FAC379F6F9C6A8F180', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
