VALUES ('doc-09-mitre-attack-p0-21587', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-04-28T12:47:25.941Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PoetRAT](https://attack.mitre.org/software/S0428) checked the size of the hard drive to determine if it was being run in a sandbox environment. In the event of sandbox detection, it would delete itself by overwriting the malware scripts with the contents of \"License.txt\" and exiting.(Citation: Talos PoetRAT April 2020)", "external_references": [{"description": "Mercer, W, et al. (2020, April 16). PoetRAT: Python RAT uses COVID-19 lures to target Azerbaijan public and private sectors. Retrieved April 27, 2020.", "source_name": "Talos PoetRAT April 2020", "url": "https://blog.talosintelligence.com/2020/04/poetrat-covid-19-lures.html"}], "id": "relationship--6340a1e8-4880-4c91-b4fd-ce909b35b87f", "modified": "2026-04-29T14:23:06.060Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--cc5497f7-a9e8-436f-94da-b2b4a9b9ad3c", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21587', 0, 107, '09-mitre-attack', 'retrieved', '024105D6C194BA9611175AE2FBA56D2775362C0BAA9A462ED32A67736E8E394B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
