VALUES ('doc-09-mitre-attack-p0-21618', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T18:00:37.927Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CHOPSTICK](https://attack.mitre.org/software/S0023) may store RC4 encrypted configuration information in the Windows Registry.(Citation: FireEye APT28)", "external_references": [{"description": "FireEye. (2015). APT28: A WINDOW INTO RUSSIA’S CYBER ESPIONAGE OPERATIONS?. Retrieved August 19, 2015.", "source_name": "FireEye APT28", "url": "https://web.archive.org/web/20151022204649/https://www.fireeye.com/content/dam/fireeye-www/global/en/current-threats/pdfs/rpt-apt28.pdf"}], "id": "relationship--8a6bfa36-adff-402d-9913-be2e45bc22aa", "modified": "2026-04-29T14:23:06.114Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ccd61dfc-b03f-4689-8c18-7c97eab08472", "spec_version": "2.1", "target_ref": "attack-pattern--02c5abff-30bf-4703-ab92-1f6072fae939", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21618', 0, 63, '09-mitre-attack', 'retrieved', '2EE04E70577FA4D89E65FBEAB03FB262B358E7FD6A2970F5BF6A9F9E9BE01582', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
