VALUES ('doc-09-mitre-attack-p0-21757', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T20:53:00.881Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SPAWNCHIMERA](https://attack.mitre.org/software/S9024) has searched the contents of two Python files scanner.py and scanner_legacy.py by searching for specific lines and replacing them with values that reduce their ability to track mismatches or new files.(Citation: CISA SPAWNCHIMERA RESURGE February 2026)", "external_references": [{"description": "DHS/CISA. (2026, February 26). MAR-25993211-r1.v2 Ivanti Connect Secure (RESURGE): AR25-087A. Retrieved April 17, 2026.", "source_name": "CISA SPAWNCHIMERA RESURGE February 2026", "url": "https://www.cisa.gov/news-events/analysis-reports/ar25-087a"}], "id": "relationship--60e86d7e-a3b9-4929-9933-84aba4a45ff3", "modified": "2026-04-29T14:23:06.057Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d1974f35-0e06-478e-bc74-7530545d814b", "spec_version": "2.1", "target_ref": "attack-pattern--cc3502b5-30cc-4473-ad48-42d51a6ef6d1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21757', 0, 90, '09-mitre-attack', 'retrieved', 'DCA3649AEC9655A6C8D814649437A0696A0A8E6606BC8CB72875EBEECEF0D3F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
