VALUES ('doc-09-mitre-attack-p0-21763', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T21:03:34.353Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SPAWNCHIMERA](https://attack.mitre.org/software/S9024) has disabled logging and log forwarding on Ivanti devices targeting the `dslogserver` process.(Citation: CISA SPAWNCHIMERA RESURGE February 2026)(Citation: Google UNC5221 Ivanti April 2025)(Citation: Google UNC5221 BRICKSTORM SPAWNCHIMERA April 2024)(Citation: Picus Security UNC5221 Ivanti May 2025)", "external_references": [{"description": "DHS/CISA. (2026, February 26). MAR-25993211-r1.v2 Ivanti Connect Secure (RESURGE): AR25-087A. Retrieved April 17, 2026.", "source_name": "CISA SPAWNCHIMERA RESURGE February 2026", "url": "https://www.cisa.gov/news-events/analysis-reports/ar25-087a"}, {"description": "John Wolfram, Michael Edie, Jacob Thompson, Matt Lin, Josh Murchie. (2025, April 3). Suspected China-Nexus Threat Actor Actively Exploiting Critical Ivanti Connect Secure Vulnerability (CVE-2025-22457). Retrieved April 13, 2026.", "source_name": "Google UNC5221 Ivanti April 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-exploiting-critical-ivanti-vulnerability"}, {"description": "Matt Lin, Austin Larsen, John Wolfram, Ashley Pearson, Josh Murchie, Lukasz Lamparski, Joseph Pisano, Ryan Hall, Ron Craft, Shawn Crew, Billy Wong, Tyler McLellan. (2024, April 4). Cutting Edge, Part 4: Ivanti Connect Secure VPN Post-Exploitation Lateral Movement Case Studies. Retrieved April 16, 2026.", "source_name": "Google UNC5221 BRICKSTORM SPAWNCHIMERA April 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/ivanti-post-exploitation-lateral-movement"}, {"description": "Sila Ozeren Hacioglu. (2025, May 5). UNC5221’s Latest Exploit: Weaponizing CVE-2025-22457 in Ivanti Connect Secure. Retrieved April 13, 2026.", "source_name": "Picus Security UNC5221 Ivanti May 2025", "url": "https://www.picussecurity.com/resource/blog/unc5221-cve-2025-22457-ivanti-connect-secure"}], "id": "relationship--ba2f665e-0241-463b-a49a-076d8f5bb5a1", "modified": "2026-04-29T14:23:06.179Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d1974f35-0e06-478e-bc74-7530545d814b", "spec_version": "2.1", "target_ref": "attack-pattern--b831f51c-d22f-4724-bbab-60d056bd1150", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21763', 0, 210, '09-mitre-attack', 'retrieved', '2BA8D4A182E77A0BEFE0FA28FEA8CD95666E628832C02613F34CB6564F425A62', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
