VALUES ('doc-09-mitre-attack-p0-21769', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T21:15:13.745Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SPAWNCHIMERA](https://attack.mitre.org/software/S9024) has obtained system information such as release, uptime, and current time.(Citation: Google UNC5221 BRICKSTORM SPAWNCHIMERA April 2024) ", "external_references": [{"description": "Matt Lin, Austin Larsen, John Wolfram, Ashley Pearson, Josh Murchie, Lukasz Lamparski, Joseph Pisano, Ryan Hall, Ron Craft, Shawn Crew, Billy Wong, Tyler McLellan. (2024, April 4). Cutting Edge, Part 4: Ivanti Connect Secure VPN Post-Exploitation Lateral Movement Case Studies. Retrieved April 16, 2026.", "source_name": "Google UNC5221 BRICKSTORM SPAWNCHIMERA April 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/ivanti-post-exploitation-lateral-movement"}], "id": "relationship--fbcc97eb-3768-4c8f-b00e-eb84a69fc0da", "modified": "2026-04-29T14:23:06.267Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d1974f35-0e06-478e-bc74-7530545d814b", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21769', 0, 103, '09-mitre-attack', 'retrieved', '9DCC3A3EB94270B4B68A4118493B107A8CB7CA1E288E00A25566D89AC984DDEB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
