VALUES ('doc-09-mitre-attack-p0-21770', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T21:19:16.917Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SPAWNCHIMERA](https://attack.mitre.org/software/S9024) has fixed a buffer overflow vulnerability (CVE-2025-0282) by hooking the strncpy function and limiting the size to 256 to prevent other actors from leveraging the exploit.(Citation: JPCERT SPAWNCHIMERA Ivanti February 2025) [SPAWNCHIMERA](https://attack.mitre.org/software/S9024) has converted its process name to hexadecimal and verifies an added value which is triggered when the first byte of the source copied to the fixed strncpy function matches `0x04050203`.(Citation: JPCERT SPAWNCHIMERA Ivanti February 2025)", "external_references": [{"description": "Yuma Masubuchi. (2025, February 20). SPAWNCHIMERA Malware: The Chimera Spawning from Ivanti Connect Secure Vulnerability. Retrieved April 17, 2026.", "source_name": "JPCERT SPAWNCHIMERA Ivanti February 2025", "url": "https://blogs.jpcert.or.jp/en/2025/02/spawnchimera.html"}], "id": "relationship--fd429e36-81b7-4e3d-a537-e27c0c6258d1", "modified": "2026-04-29T14:23:06.269Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d1974f35-0e06-478e-bc74-7530545d814b", "spec_version": "2.1", "target_ref": "attack-pattern--49fca0d2-685d-41eb-8bd4-05451cc3a742", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21770', 0, 126, '09-mitre-attack', 'retrieved', 'B1C8A89BCECE6DB50DE5E1618B13F7F239E4462F035C6BC6EC3F5055AF0C8DB3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
