VALUES ('doc-09-mitre-attack-p0-21851', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-02-18T20:33:58.908Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BONDUPDATER](https://attack.mitre.org/software/S0360) can read batch commands in a file sent from its C2 server and execute them with cmd.exe.(Citation: Palo Alto OilRig Sep 2018)", "external_references": [{"description": "Wilhoit, K. and Falcone, R. (2018, September 12). OilRig Uses Updated BONDUPDATER to Target Middle Eastern Government. Retrieved February 18, 2019.", "source_name": "Palo Alto OilRig Sep 2018", "url": "https://unit42.paloaltonetworks.com/unit42-oilrig-uses-updated-bondupdater-target-middle-eastern-government/"}], "id": "relationship--30f18b5b-a02e-4d15-bfd2-346145453a07", "modified": "2026-04-29T14:23:05.979Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d5268dfb-ae2b-4e0e-ac07-02a460613d8a", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21851', 0, 83, '09-mitre-attack', 'retrieved', '43A53DA6E08153EE364700A8983D0E52253E733DE24246B551F8C67002324C9F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
