VALUES ('doc-09-mitre-attack-p0-21868', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-17T19:53:56.907Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Troll Stealer](https://attack.mitre.org/software/S1196) is typically installed via a dropper file that masquerades as a legitimate security program installation file.(Citation: S2W Troll Stealer 2024)(Citation: Symantec Troll Stealer 2024)", "external_references": [{"description": "Jiho Kim & Sebin Lee, S2W. (2024, February 7). Kimsuky disguised as a Korean company signed with a valid certificate to distribute Troll Stealer (English ver.). Retrieved January 17, 2025.", "source_name": "S2W Troll Stealer 2024", "url": "https://medium.com/s2wblog/kimsuky-disguised-as-a-korean-company-signed-with-a-valid-certificate-to-distribute-troll-stealer-cfa5d54314e2"}, {"description": "Symantec Threat Hunter Team. (2024, May 16). Springtail: New Linux Backdoor Added to Toolkit. Retrieved January 17, 2025.", "source_name": "Symantec Troll Stealer 2024", "url": "https://www.security.com/threat-intelligence/springtail-kimsuky-backdoor-espionage"}], "id": "relationship--55eb87ba-64a9-4720-a3ce-fe03f66b074c", "modified": "2026-04-29T14:23:06.042Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d6748457-75c2-4989-a41f-2d017994057e", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21868', 0, 120, '09-mitre-attack', 'retrieved', 'DB750522DE01712DF9D722819B4279D8543D856DC1C1C9F7D23DCDC343A0BB3F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
