VALUES ('doc-09-mitre-attack-p0-21869', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-17T20:11:35.144Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Troll Stealer](https://attack.mitre.org/software/S1196) collects all data in victim `.ssh` folders by creating a compressed copy that is subsequently exfiltrated to command and control infrastructure. [Troll Stealer](https://attack.mitre.org/software/S1196) also collects key information associated with the Government Public Key Infrastructure (GPKI) service for South Korean government information systems.(Citation: S2W Troll Stealer 2024)(Citation: Symantec Troll Stealer 2024)", "external_references": [{"description": "Jiho Kim & Sebin Lee, S2W. (2024, February 7). Kimsuky disguised as a Korean company signed with a valid certificate to distribute Troll Stealer (English ver.). Retrieved January 17, 2025.", "source_name": "S2W Troll Stealer 2024", "url": "https://medium.com/s2wblog/kimsuky-disguised-as-a-korean-company-signed-with-a-valid-certificate-to-distribute-troll-stealer-cfa5d54314e2"}, {"description": "Symantec Threat Hunter Team. (2024, May 16). Springtail: New Linux Backdoor Added to Toolkit. Retrieved January 17, 2025.", "source_name": "Symantec Troll Stealer 2024", "url": "https://www.security.com/threat-intelligence/springtail-kimsuky-backdoor-espionage"}], "id": "relationship--61ccf81a-471a-4ab4-aee7-de3a3084f211", "modified": "2026-04-29T14:23:06.058Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d6748457-75c2-4989-a41f-2d017994057e", "spec_version": "2.1", "target_ref": "attack-pattern--60b508a1-6a5e-46b1-821a-9f7b78752abf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21869', 0, 146,