VALUES ('doc-09-mitre-attack-p0-21880', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BLACKCOFFEE](https://attack.mitre.org/software/S0069) has the capability to enumerate files.(Citation: FireEye APT17)", "external_references": [{"description": "FireEye Labs/FireEye Threat Intelligence. (2015, May 14). Hiding in Plain Sight: FireEye and Microsoft Expose Obfuscation Tactic. Retrieved November 17, 2024.", "source_name": "FireEye APT17", "url": "https://web.archive.org/web/20240119213200/https://www2.fireeye.com/rs/fireye/images/APT17_Report.pdf"}], "id": "relationship--007cc21a-685a-4701-99c1-20f258cedc7c", "modified": "2026-04-29T14:23:05.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d69c8146-ab35-4d50-8382-6fc80e641d43", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21880', 0, 66, '09-mitre-attack', 'retrieved', '8A68E4C58FDA4ABF27CC2E036761D2518C382862CA645DCA8B1442AB8CE218AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
