VALUES ('doc-09-mitre-attack-p0-21886', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-20T21:04:48.879Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BLACKCOFFEE](https://attack.mitre.org/software/S0069) has also obfuscated its C2 traffic as normal traffic to sites such as Github.(Citation: FireEye APT17)(Citation: FireEye Periscope March 2018)", "external_references": [{"description": "FireEye Labs/FireEye Threat Intelligence. (2015, May 14). Hiding in Plain Sight: FireEye and Microsoft Expose Obfuscation Tactic. Retrieved November 17, 2024.", "source_name": "FireEye APT17", "url": "https://web.archive.org/web/20240119213200/https://www2.fireeye.com/rs/fireye/images/APT17_Report.pdf"}, {"description": "FireEye. (2018, March 16). Suspected Chinese Cyber Espionage Group (TEMP.Periscope) Targeting U.S. Engineering and Maritime Industries. Retrieved April 11, 2018.", "source_name": "FireEye Periscope March 2018", "url": "https://www.fireeye.com/blog/threat-research/2018/03/suspected-chinese-espionage-group-targeting-maritime-and-engineering-industries.html"}], "id": "relationship--fd6055a0-7db2-4135-a87f-156354c97f0b", "modified": "2026-04-29T14:23:06.269Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d69c8146-ab35-4d50-8382-6fc80e641d43", "spec_version": "2.1", "target_ref": "attack-pattern--be055942-6e63-49d7-9fa1-9cb7d8a8f3f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21886', 0, 106, '09-mitre-attack', 'retrieved', '12DC393AD931A1222972295FAB4815EFCE30654F42C473A2EB04C9E21F00B0EC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
