VALUES ('doc-09-mitre-attack-p0-21887', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:57:04.969Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BFG Agonizer](https://attack.mitre.org/software/S1136) uses elevated privileges to call NtRaiseHardError to induce a \"blue screen of death\" on infected systems, causing a system crash. Once shut down, the system is no longer bootable.(Citation: Unit42 Agrius 2023)", "external_references": [{"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "relationship--17b73eb6-f4a6-49d4-8f72-18796cf7d553", "modified": "2026-04-29T14:23:05.937Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d6aefbbf-fbef-485a-973e-b5403d8f8b18", "spec_version": "2.1", "target_ref": "attack-pattern--ff73aa03-0090-4464-83ac-f89e233c02bc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21887', 0, 99, '09-mitre-attack', 'retrieved', '9165DB92EE22003241D21EBDF45F9B1616099818E213D30032C68CC85A9F2725', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
