VALUES ('doc-09-mitre-attack-p0-21889', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:55:27.115Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BFG Agonizer](https://attack.mitre.org/software/S1136) retrieves a device handle to \\\\\\\\.\\\\PhysicalDrive0 to wipe the boot sector of a given disk.(Citation: Unit42 Agrius 2023)", "external_references": [{"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "relationship--7145e20d-4c16-47bf-bf13-40b4e031d0e5", "modified": "2026-04-29T14:23:06.080Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d6aefbbf-fbef-485a-973e-b5403d8f8b18", "spec_version": "2.1", "target_ref": "attack-pattern--0af0ca99-357d-4ba1-805f-674fdfb7bef9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21889', 0, 85, '09-mitre-attack', 'retrieved', 'A0625BB30B7FC6E258B0623CB0A0E0B8AF120AA28951C1E592734B348D40AF51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
