VALUES ('doc-09-mitre-attack-p0-21897', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-23T17:01:00.356Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ebury](https://attack.mitre.org/software/S0377) can intercept private keys using a trojanized ssh-add function.(Citation: ESET Ebury Feb 2014)", "external_references": [{"description": "M.Léveillé, M.. (2014, February 21). An In-depth Analysis of Linux/Ebury. Retrieved April 19, 2019.", "source_name": "ESET Ebury Feb 2014", "url": "https://www.welivesecurity.com/2014/02/21/an-in-depth-analysis-of-linuxebury/"}], "id": "relationship--5b5a618e-3a67-4223-a158-af4ce7e0c7d9", "modified": "2026-04-29T14:23:06.050Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d6b3fcd0-1c86-4350-96f0-965ed02fcc51", "spec_version": "2.1", "target_ref": "attack-pattern--f4c1826f-a322-41cd-9557-562100848c84", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21897', 0, 66, '09-mitre-attack', 'retrieved', 'B9FD266474F91FF445E839F8E1216DB7CDC853BD1CA6E1EE4A17174B07009589', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
