VALUES ('doc-09-mitre-attack-p0-21898', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-10T21:09:24.339Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If credentials are not collected for two weeks, [Ebury](https://attack.mitre.org/software/S0377) encrypts the credentials using a public key and sends them via UDP to an IP address located in the DNS TXT record.(Citation: ESET Windigo Mar 2014)(Citation: ESET Ebury May 2024)", "external_references": [{"description": "Bilodeau, O., Bureau, M., Calvet, J., Dorais-Joncas, A., Léveillé, M., Vanheuverzwijn, B. (2014, March 18). Operation Windigo – the vivisection of a large Linux server‑side credential‑stealing malware campaign. Retrieved February 10, 2021.", "source_name": "ESET Windigo Mar 2014", "url": "https://www.welivesecurity.com/2014/03/18/operation-windigo-the-vivisection-of-a-large-linux-server-side-credential-stealing-malware-campaign/"}, {"description": "Marc-Etienne M.Léveillé. (2024, May 1). Ebury is alive but unseen. Retrieved May 21, 2024.", "source_name": "ESET Ebury May 2024", "url": "https://web-assets.esetstatic.com/wls/en/papers/white-papers/ebury-is-alive-but-unseen.pdf"}], "id": "relationship--6ff6558d-3efb-4219-8d47-ecf82755ccf1", "modified": "2026-04-29T14:23:06.078Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d6b3fcd0-1c86-4350-96f0-965ed02fcc51", "spec_version": "2.1", "target_ref": "attack-pattern--774a3188-6ba9-4dc4-879d-d54ee48a5ce9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21898', 0, 131, '09-mitre-attack', 'retrieved', '1A5B89061E62EC0B4410C8383CA38E95B301D8C87D95234F2332BF913C8DFAC5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": 