VALUES ('doc-09-mitre-attack-p0-21905', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-23T22:56:14.733Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ebury](https://attack.mitre.org/software/S0377) has used Python to implement its DGA.(Citation: ESET Ebury Oct 2017)\t", "external_references": [{"description": "Vachon, F. (2017, October 30). Windigo Still not Windigone: An Ebury Update . Retrieved February 10, 2021.", "source_name": "ESET Ebury Oct 2017", "url": "https://www.welivesecurity.com/2017/10/30/windigo-ebury-update-2/"}], "id": "relationship--c1806927-2279-4597-ada9-e0c06b65b7eb", "modified": "2026-04-29T14:23:06.190Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d6b3fcd0-1c86-4350-96f0-965ed02fcc51", "spec_version": "2.1", "target_ref": "attack-pattern--cc3502b5-30cc-4473-ad48-42d51a6ef6d1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21905', 0, 67, '09-mitre-attack', 'retrieved', '056800E02EB980AC89E1A04F3BB0CC526F1023A73E9DC813B7A79408E0EF8489', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
