INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-21906', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-10T18:41:29.200Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "When [Ebury](https://attack.mitre.org/software/S0377) is running as an OpenSSH server, it uses LD_PRELOAD to inject its malicious shared module in to programs launched by SSH sessions. [Ebury](https://attack.mitre.org/software/S0377) hooks the following functions from `libc` to inject into subprocesses; `system`, `popen`, `execve`, `execvpe`, `execv`, `execvp`, and `execl`.(Citation: ESET Ebury Oct 2017)(Citation: ESET Ebury May 2024)", "external_references": [{"description": "Marc-Etienne M.Léveillé. (2024, May 1). Ebury is alive but unseen. Retrieved May 21, 2024.", "source_name": "ESET Ebury May 2024", "url": "https://web-assets.esetstatic.com/wls/en/papers/white-papers/ebury-is-alive-but-unseen.pdf"}, {"description": "Vachon, F. (2017, October 30). Windigo Still not Windigone: An Ebury Update . Retrieved February 10, 2021.", "source_name": "ESET Ebury Oct 2017", "url": "https://www.welivesecurity.com/2017/10/30/windigo-ebury-update-2/"}], "id": "relationship--d3102278-dab8-485c-9cd2-52f80c4da8bd", "modified": "2026-04-29T14:23:06.214Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d6b3fcd0-1c86-4350-96f0-965ed02fcc51", "spec_version": "2.1", "target_ref": "attack-pattern--633a100c-b2c9-41bf-9be5-905c1b16c825", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21906', 0, 128, '09-mitre-attack', 'retrieved', 'D35A56CB178A8D729804CD96B4624BC4A6C4C1009E7E0DB03A916047B369B659', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
