VALUES ('doc-09-mitre-attack-p0-21934', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-13T11:55:04.213Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Meteor](https://attack.mitre.org/software/S0688) can disconnect all network adapters on a compromised host using `powershell -Command \"Get-WmiObject -class Win32_NetworkAdapter | ForEach { If ($.NetEnabled) { $.Disable() } }\" > NUL`.(Citation: Check Point Meteor Aug 2021)", "external_references": [{"description": "Check Point Research Team. (2021, August 14). Indra - Hackers Behind Recent Attacks on Iran. Retrieved February 17, 2022.", "source_name": "Check Point Meteor Aug 2021", "url": "https://research.checkpoint.com/2021/indra-hackers-behind-recent-attacks-on-iran/"}], "id": "relationship--0f677d2e-2cff-4b9f-ae1b-621a5e856b08", "modified": "2026-04-29T14:23:05.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d79e7a60-5de9-448e-a074-f95d2d80f8d0", "spec_version": "2.1", "target_ref": "attack-pattern--20fb2507-d71c-455d-9b6d-6104461cf26b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21934', 0, 90, '09-mitre-attack', 'retrieved', '6EDE2687B941344B471CAC20805CB8368967A8CAA1D53826015F3CE6C94BAA85', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
