VALUES ('doc-09-mitre-attack-p0-21937', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-07T19:33:01.780Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Meteor](https://attack.mitre.org/software/S0688) can use [Wevtutil](https://attack.mitre.org/software/S0645) to remove Security, System and Application Event Viewer logs.(Citation: Check Point Meteor Aug 2021)", "external_references": [{"description": "Check Point Research Team. (2021, August 14). Indra - Hackers Behind Recent Attacks on Iran. Retrieved February 17, 2022.", "source_name": "Check Point Meteor Aug 2021", "url": "https://research.checkpoint.com/2021/indra-hackers-behind-recent-attacks-on-iran/"}], "id": "relationship--3cfabaa7-ee34-4299-939d-66530d7bce62", "modified": "2026-04-29T14:23:06.008Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d79e7a60-5de9-448e-a074-f95d2d80f8d0", "spec_version": "2.1", "target_ref": "attack-pattern--75b9a4d2-d4e2-4ca1-9aab-1badd9e05fd0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21937', 0, 76, '09-mitre-attack', 'retrieved', '277418D75CAD2D4ABED4F6B16D764DE184DCF05B9500885453BC4B25A2CB9A62', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
