VALUES ('doc-09-mitre-attack-p0-21944', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-07T19:33:01.775Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Meteor](https://attack.mitre.org/software/S0688) has the ability to discover the hostname of a compromised host.(Citation: Check Point Meteor Aug 2021)", "external_references": [{"description": "Check Point Research Team. (2021, August 14). Indra - Hackers Behind Recent Attacks on Iran. Retrieved February 17, 2022.", "source_name": "Check Point Meteor Aug 2021", "url": "https://research.checkpoint.com/2021/indra-hackers-behind-recent-attacks-on-iran/"}], "id": "relationship--c3893875-4f9e-43e4-babf-6f45ec485444", "modified": "2026-04-29T14:23:06.192Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d79e7a60-5de9-448e-a074-f95d2d80f8d0", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21944', 0, 75, '09-mitre-attack', 'retrieved', 'AFB76FA70266571D2C26CE990675C772473EA73E6144197065970452F2694E71', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
