VALUES ('doc-09-mitre-attack-p0-21953', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-05T14:33:01.097Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[njRAT](https://attack.mitre.org/software/S0385) enumerates the victim operating system and computer name during the initial infection.(Citation: Fidelis njRAT June 2013)", "external_references": [{"description": "Fidelis Cybersecurity. (2013, June 28). Fidelis Threat Advisory #1009: \"njRAT\" Uncovered. Retrieved June 4, 2019.", "source_name": "Fidelis njRAT June 2013", "url": "https://www.threatminer.org/_reports/2013/fta-1009---njrat-uncovered-1.pdf"}], "id": "relationship--005cbf7d-9d0b-443b-91db-7b148a1eb55b", "modified": "2026-04-29T14:23:05.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d906e6f7-434c-44c0-b51a-ed50af8f7945", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21953', 0, 70, '09-mitre-attack', 'retrieved', '9A488E701B9EBAF64835329521CE3B16120545D9F3E38B824D784A29EBDCE5F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
