VALUES ('doc-09-mitre-attack-p0-21954', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T18:57:11.074Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[njRAT](https://attack.mitre.org/software/S0385) has a module that steals passwords saved in victim web browsers.(Citation: Fidelis njRAT June 2013)(Citation: Trend Micro njRAT 2018)(Citation: Citizen Lab Group5)", "external_references": [{"description": "Fidelis Cybersecurity. (2013, June 28). Fidelis Threat Advisory #1009: \"njRAT\" Uncovered. Retrieved June 4, 2019.", "source_name": "Fidelis njRAT June 2013", "url": "https://www.threatminer.org/_reports/2013/fta-1009---njrat-uncovered-1.pdf"}, {"description": "Pascual, C. (2018, November 27). AutoIt-Compiled Worm Affecting Removable Media Delivers Fileless Version of BLADABINDI/njRAT Backdoor. Retrieved June 4, 2019.", "source_name": "Trend Micro njRAT 2018", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/autoit-compiled-worm-affecting-removable-media-delivers-fileless-version-of-bladabindi-njrat-backdoor/"}, {"description": "Scott-Railton, J., et al. (2016, August 2). Group5: Syria and the Iranian Connection. Retrieved September 26, 2016.", "source_name": "Citizen Lab Group5", "url": "https://citizenlab.ca/2016/08/group5-syria/"}], "id": "relationship--07773227-54d9-4476-877a-739c490b7b65", "modified": "2026-04-29T14:23:05.913Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d906e6f7-434c-44c0-b51a-ed50af8f7945", "spec_version": "2.1", "target_ref": "attack-pattern--58a3e6aa-4453-4cc8-a51f-4befe80b31a8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21954', 0, 128, '09-mitre-attack', 'retrieved', '080ACF904AE4A78A70337995DE96B4C