VALUES ('doc-09-mitre-attack-p0-21956', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-04T19:48:14.179Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[njRAT](https://attack.mitre.org/software/S0385) can download files to the victim’s machine.(Citation: Fidelis njRAT June 2013)(Citation: Trend Micro njRAT 2018) [APT-C-36](https://attack.mitre.org/groups/G0099) has used modified versions of [njRAT](https://attack.mitre.org/software/S0385) to enable the download of .NET assemblies.(Citation: Kaspersky BlindEagle AUG 2024)", "external_references": [{"description": "Fidelis Cybersecurity. (2013, June 28). Fidelis Threat Advisory #1009: \"njRAT\" Uncovered. Retrieved June 4, 2019.", "source_name": "Fidelis njRAT June 2013", "url": "https://www.threatminer.org/_reports/2013/fta-1009---njrat-uncovered-1.pdf"}, {"description": "Global Research & Analysis Team, Kaspersky. (2024, August 19). BlindEagle flying high in Latin America. Retrieved April 16, 2026.", "source_name": "Kaspersky BlindEagle AUG 2024", "url": "https://securelist.com/blindeagle-apt/113414/"}, {"description": "Pascual, C. (2018, November 27). AutoIt-Compiled Worm Affecting Removable Media Delivers Fileless Version of BLADABINDI/njRAT Backdoor. Retrieved June 4, 2019.", "source_name": "Trend Micro njRAT 2018", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/autoit-compiled-worm-affecting-removable-media-delivers-fileless-version-of-bladabindi-njrat-backdoor/"}], "id": "relationship--168ab4a2-db4d-4d64-9951-6547145aabe6", "modified": "2026-04-29T14:23:05.935Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d906e6f7-434c-44c0-b51a-ed50af8f7945", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21956', 0, 142, '09-mitre-attack', 'retrieved', 'EC6BEE92D37A6C1D7BE6D0CFE0AD551BFF74AC63D2E6CD50BAC7B32B840F4B5D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
