VALUES ('doc-09-mitre-attack-p0-21988', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-04T18:59:41.952Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZIPLINE](https://attack.mitre.org/software/S1114) can use AES-128-CBC to encrypt data for both upload and download.(Citation: Mandiant Cutting Edge Part 2 January 2024)", "external_references": [{"description": "Lin, M. et al. (2024, January 31). Cutting Edge, Part 2: Investigating Ivanti Connect Secure VPN Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge Part 2 January 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-zero-day-exploitation"}], "id": "relationship--7965d9c8-82db-4fde-a017-27e4de931546", "modified": "2026-04-29T14:23:06.091Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9765cbd-4c88-4805-ba98-4c6ccb56b864", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21988', 0, 82, '09-mitre-attack', 'retrieved', '3E2CEBDEA0A943D79260BEC4FB62F85B7B612D5AF156E1E6DC81C32DF7506B41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
