VALUES ('doc-09-mitre-attack-p0-21989', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-04T19:11:59.190Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZIPLINE](https://attack.mitre.org/software/S1114) can use `/bin/sh` to create a reverse shell and execute commands.(Citation: Mandiant Cutting Edge January 2024) ", "external_references": [{"description": "McLellan, T. et al. (2024, January 12). Cutting Edge: Suspected APT Targets Ivanti Connect Secure VPN in New Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge January 2024", "url": "https://www.mandiant.com/resources/blog/suspected-apt-targets-ivanti-zero-day"}], "id": "relationship--8c85fcbd-cb56-45be-ba9f-ba67177f2785", "modified": "2026-04-29T14:23:06.117Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9765cbd-4c88-4805-ba98-4c6ccb56b864", "spec_version": "2.1", "target_ref": "attack-pattern--a9d4b653-6915-42af-98b2-5758c4ceee56", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21989', 0, 81, '09-mitre-attack', 'retrieved', '2245EABDAE83C2F1DC9B95A28DA199EF0D2A532999801E3033F7ADD12FA2A1DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
