VALUES ('doc-09-mitre-attack-p0-21991', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-04T19:05:49.846Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZIPLINE](https://attack.mitre.org/software/S1114) can download files to be saved on the compromised system.(Citation: Mandiant Cutting Edge January 2024)(Citation: Mandiant Cutting Edge Part 2 January 2024)", "external_references": [{"description": "Lin, M. et al. (2024, January 31). Cutting Edge, Part 2: Investigating Ivanti Connect Secure VPN Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge Part 2 January 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-zero-day-exploitation"}, {"description": "McLellan, T. et al. (2024, January 12). Cutting Edge: Suspected APT Targets Ivanti Connect Secure VPN in New Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge January 2024", "url": "https://www.mandiant.com/resources/blog/suspected-apt-targets-ivanti-zero-day"}], "id": "relationship--e34a0e21-1db1-4c11-8e71-07bae802d8b9", "modified": "2026-04-29T14:23:06.235Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9765cbd-4c88-4805-ba98-4c6ccb56b864", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21991', 0, 119, '09-mitre-attack', 'retrieved', '62F07BA94F614518C2A5C9B00525F44D4E93AAA34EF293AA138228007C1C3115', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
