VALUES ('doc-09-mitre-attack-p0-21992', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-04T19:31:50.138Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " [ZIPLINE](https://attack.mitre.org/software/S1114) can add itself to the exclusion list for the Ivanti Connect Secure Integrity Checker Tool if the `--exclude` parameter is passed by the `tar` process.(Citation: Mandiant Cutting Edge January 2024)", "external_references": [{"description": "McLellan, T. et al. (2024, January 12). Cutting Edge: Suspected APT Targets Ivanti Connect Secure VPN in New Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge January 2024", "url": "https://www.mandiant.com/resources/blog/suspected-apt-targets-ivanti-zero-day"}], "id": "relationship--f4666906-29a5-48ff-9f9a-2d0b4ad4fc45", "modified": "2026-04-29T14:23:06.257Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9765cbd-4c88-4805-ba98-4c6ccb56b864", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21992', 0, 95, '09-mitre-attack', 'retrieved', '099F3824888D50DFBB912484431F55544937302A4A7317A61939CF5058D3B400', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
