VALUES ('doc-09-mitre-attack-p0-21994', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T17:31:39.486Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Maze](https://attack.mitre.org/software/S0449) has inserted large blocks of junk code, including some components to decrypt strings and other important information for later in the encryption process.(Citation: McAfee Maze March 2020)", "external_references": [{"description": "Mundo, A. (2020, March 26). Ransomware Maze. Retrieved May 18, 2020.", "source_name": "McAfee Maze March 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/ransomware-maze/"}], "id": "relationship--0bbdc984-1515-4a8e-a211-2817371fc75e", "modified": "2026-04-29T14:23:05.919Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9f7383c-95ec-4080-bbce-121c9384457b", "spec_version": "2.1", "target_ref": "attack-pattern--671cd17f-a765-48fd-adc4-dad1941b1ae3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21994', 0, 77, '09-mitre-attack', 'retrieved', 'C0E874C3ECA30B68F63390D04475D95DB8F79D9AD576EE3967153ACA31A7EB8A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
