VALUES ('doc-09-mitre-attack-p0-21999', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T17:31:39.376Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Maze](https://attack.mitre.org/software/S0449) has used the \"WNetOpenEnumW\", \"WNetEnumResourceW”, “WNetCloseEnum” and “WNetAddConnection2W” functions to enumerate the network resources on the infected machine.(Citation: McAfee Maze March 2020)", "external_references": [{"description": "Mundo, A. (2020, March 26). Ransomware Maze. Retrieved May 18, 2020.", "source_name": "McAfee Maze March 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/ransomware-maze/"}], "id": "relationship--2f3d9b76-bec9-4cee-9a9b-1c42f373ec86", "modified": "2026-04-29T14:23:05.970Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9f7383c-95ec-4080-bbce-121c9384457b", "spec_version": "2.1", "target_ref": "attack-pattern--7e150503-88e7-4861-866b-ff1ac82c4475", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21999', 0, 72, '09-mitre-attack', 'retrieved', 'BA46CD93E8CD3D977603EB63F4BCB80A2160B4621091F9F96FC6009AC13CC39E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
