VALUES ('doc-09-mitre-attack-p0-22001', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T17:31:39.355Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Maze](https://attack.mitre.org/software/S0449) has injected the malware DLL into a target process.(Citation: McAfee Maze March 2020)(Citation: Sophos Maze VM September 2020)\t", "external_references": [{"description": "Mundo, A. (2020, March 26). Ransomware Maze. Retrieved May 18, 2020.", "source_name": "McAfee Maze March 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/ransomware-maze/"}, {"description": "Brandt, A., Mackenzie, P.. (2020, September 17). Maze Attackers Adopt Ragnar Locker Virtual Machine Technique. Retrieved October 9, 2020.", "source_name": "Sophos Maze VM September 2020", "url": "https://news.sophos.com/en-us/2020/09/17/maze-attackers-adopt-ragnar-locker-virtual-machine-technique/"}], "id": "relationship--44fab50d-4fb6-4a8a-ab7a-84dcb70443f5", "modified": "2026-04-29T14:23:06.020Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9f7383c-95ec-4080-bbce-121c9384457b", "spec_version": "2.1", "target_ref": "attack-pattern--f4599aa0-4f85-4a32-80ea-fc39dc965945", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22001', 0, 96, '09-mitre-attack', 'retrieved', 'D08BBA571B8425D2A6A9FA4E90A47CA48904E0B9FA62C9526F81EBB9B5B40F3D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
