VALUES ('doc-09-mitre-attack-p0-22008', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T17:31:39.464Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Maze](https://attack.mitre.org/software/S0449) has disabled dynamic analysis and other security tools including IDA debugger, x32dbg, and OllyDbg.(Citation: McAfee Maze March 2020) It has also disabled Windows Defender''s Real-Time Monitoring feature and attempted to disable endpoint protection services.(Citation: Sophos Maze VM September 2020)", "external_references": [{"description": "Mundo, A. (2020, March 26). Ransomware Maze. Retrieved May 18, 2020.", "source_name": "McAfee Maze March 2020", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/ransomware-maze/"}, {"description": "Brandt, A., Mackenzie, P.. (2020, September 17). Maze Attackers Adopt Ragnar Locker Virtual Machine Technique. Retrieved October 9, 2020.", "source_name": "Sophos Maze VM September 2020", "url": "https://news.sophos.com/en-us/2020/09/17/maze-attackers-adopt-ragnar-locker-virtual-machine-technique/"}], "id": "relationship--adbff6cf-1e16-460e-88ed-a0288ab32e68", "modified": "2026-04-29T14:23:06.161Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9f7383c-95ec-4080-bbce-121c9384457b", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22008', 0, 117, '09-mitre-attack', 'retrieved', '7DE29F340D912B42ACCFBAE0C4B38961E0C8F5EF58455E9577B98E8AAF6B993F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
