VALUES ('doc-09-mitre-attack-p0-22014', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-09T16:24:39.960Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Maze](https://attack.mitre.org/software/S0449) has delivered components for its ransomware attacks using MSI files, some of which have been executed from the command-line using msiexec .(Citation: Sophos Maze VM September 2020)", "external_references": [{"description": "Brandt, A., Mackenzie, P.. (2020, September 17). Maze Attackers Adopt Ragnar Locker Virtual Machine Technique. Retrieved October 9, 2020.", "source_name": "Sophos Maze VM September 2020", "url": "https://news.sophos.com/en-us/2020/09/17/maze-attackers-adopt-ragnar-locker-virtual-machine-technique/"}], "id": "relationship--e3fa0df1-d388-4e74-b561-acc5094a8e1b", "modified": "2026-04-29T14:23:06.236Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--d9f7383c-95ec-4080-bbce-121c9384457b", "spec_version": "2.1", "target_ref": "attack-pattern--365be77f-fc0e-42ee-bac8-4faf806d9336", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22014', 0, 86, '09-mitre-attack', 'retrieved', 'EDBA2DA125822AD761CCA6CA56481E336D29D46E5100F3E14E898B7B3ED751FA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
