VALUES ('doc-09-mitre-attack-p0-22016', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-29T01:35:30.267Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOTRASH](https://attack.mitre.org/software/S0114) has used unallocated disk space between partitions for a hidden file system that stores components of the Nemesis bootkit.(Citation: FireEye Bootkits)", "external_references": [{"description": "Andonov, D., et al. (2015, December 7). Thriving Beyond The Operating System: Financial Threat Group Targets Volume Boot Record. Retrieved May 13, 2016.", "source_name": "FireEye Bootkits", "url": "https://www.fireeye.com/blog/threat-research/2015/12/fin1-targets-boot-record.html"}], "id": "relationship--29a6afc7-f051-4c26-b6a2-cad09c73180f", "modified": "2026-04-29T14:23:05.961Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--da2ef4a9-7cbe-400a-a379-e2f230f28db3", "spec_version": "2.1", "target_ref": "attack-pattern--dfebc3b7-d19d-450b-81c7-6dafe4184c04", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22016', 0, 81, '09-mitre-attack', 'retrieved', '526727B0BF89B8B6ABB161F912F61C2A60CE70697FAF34CAA4E559C4E1D227A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
