VALUES ('doc-09-mitre-attack-p0-22017', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BOOTRASH](https://attack.mitre.org/software/S0114) is a Volume Boot Record (VBR) bootkit that uses the VBR to maintain persistence.(Citation: Mandiant M Trends 2016)(Citation: FireEye Bootkits)(Citation: FireEye BOOTRASH SANS)", "external_references": [{"description": "Andonov, D., et al. (2015, December 7). Thriving Beyond The Operating System: Financial Threat Group Targets Volume Boot Record. Retrieved May 13, 2016.", "source_name": "FireEye Bootkits", "url": "https://www.fireeye.com/blog/threat-research/2015/12/fin1-targets-boot-record.html"}, {"description": "Glyer, C.. (2017, June 22). Boot What?. Retrieved November 17, 2024.", "source_name": "FireEye BOOTRASH SANS", "url": "https://web.archive.org/web/20190926040727/https://www.sans.org/cyber-security-summit/archives/file/summit-archive-1498163766.pdf"}, {"description": "Mandiant. (2016, February 25). Mandiant M-Trends 2016. Retrieved November 17, 2024.", "source_name": "Mandiant M Trends 2016", "url": "https://web.archive.org/web/20211024160454/https://www.fireeye.com/content/dam/fireeye-www/current-threats/pdfs/rpt-mtrends-2016.pdf"}], "id": "relationship--63d53308-7d7d-4777-a1cc-c7100735609c", "modified": "2026-04-29T14:23:06.061Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--da2ef4a9-7cbe-400a-a379-e2f230f28db3", "spec_version": "2.1", "target_ref": "attack-pattern--1b7b1806-7746-41a1-a35d-e48dae25ddba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22017', 0, 120, '09-mitre-attack', 'retrieved', '158FF37FD3A2F248C899F5E56913536F913BF620E0