VALUES ('doc-09-mitre-attack-p0-22020', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-08-06T19:14:00.252Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HIUPAN](https://attack.mitre.org/software/S1230) has conducted process discovery to identify the [PUBLOAD](https://attack.mitre.org/software/S1228) malware under the process WCBrowserWatcher.exe and will launch it from an install directory if it is not found.(Citation: Trend Micro MUSTANG PANDA PUBLOAD HIUPAN SEPTEMBER 2024)", "external_references": [{"description": "Lenart Bermejo, Sunny Lu, Ted Lee. (2024, September 9). Earth Preta Evolves its Attacks with New Malware and Strategies. Retrieved August 4, 2025.", "source_name": "Trend Micro MUSTANG PANDA PUBLOAD HIUPAN SEPTEMBER 2024", "url": "https://www.trendmicro.com/en_us/research/24/i/earth-preta-new-malware-and-strategies.html"}], "id": "relationship--4ecfe8a9-182e-42a7-8b4f-519004185b20", "modified": "2026-04-29T14:23:06.032Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--da43312a-0188-4949-bab3-0df9a5df0aba", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22020', 0, 100, '09-mitre-attack', 'retrieved', '9615D280AF4ECB2040F508347C83A45A4992E067D6363306D8FB05F26BE7C6C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
