VALUES ('doc-09-mitre-attack-p0-22031', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-29T04:05:19.098Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ComRAT](https://attack.mitre.org/software/S0126) can use SSL/TLS encryption for its HTTP-based C2 channel. [ComRAT](https://attack.mitre.org/software/S0126) has used public key cryptography with RSA and AES encrypted email attachments for its Gmail C2 channel.(Citation: ESET ComRAT May 2020)(Citation: CISA ComRAT Oct 2020) ", "external_references": [{"description": "Faou, M. (2020, May). From Agent.btz to ComRAT v4: A ten-year journey. Retrieved June 15, 2020.", "source_name": "ESET ComRAT May 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/05/ESET_Turla_ComRAT.pdf"}, {"description": "CISA. (2020, October 29). Malware Analysis Report (AR20-303A). Retrieved December 9, 2020.", "source_name": "CISA ComRAT Oct 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-303a"}], "id": "relationship--217ad0a6-f693-416e-9ae4-bcc0c533ce9f", "modified": "2026-04-29T14:23:05.951Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--da5880b4-f7da-4869-85f2-e0aba84b8565", "spec_version": "2.1", "target_ref": "attack-pattern--bf176076-b789-408e-8cba-7275e81c0ada", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22031', 0, 111, '09-mitre-attack', 'retrieved', 'AEBB9524E5FC0075633ABEAAA614ECD9E62981F1D160F702FA2FF4A5953E729E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
