VALUES ('doc-09-mitre-attack-p0-22036', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-22T03:33:01.664Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ComRAT](https://attack.mitre.org/software/S0126) has used encryption and base64 to obfuscate its orchestrator code in the Registry. [ComRAT](https://attack.mitre.org/software/S0126) has also used encoded PowerShell scripts.(Citation: ESET ComRAT May 2020)(Citation: CISA ComRAT Oct 2020) ", "external_references": [{"description": "CISA. (2020, October 29). Malware Analysis Report (AR20-303A). Retrieved December 9, 2020.", "source_name": "CISA ComRAT Oct 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-303a"}, {"description": "Faou, M. (2020, May). From Agent.btz to ComRAT v4: A ten-year journey. Retrieved June 15, 2020.", "source_name": "ESET ComRAT May 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/05/ESET_Turla_ComRAT.pdf"}], "id": "relationship--488fe004-cb37-4e15-a847-99c32b4fd757", "modified": "2026-04-29T14:23:06.024Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--da5880b4-f7da-4869-85f2-e0aba84b8565", "spec_version": "2.1", "target_ref": "attack-pattern--d511a6f6-4a33-41d5-bc95-c343875d1377", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22036', 0, 104, '09-mitre-attack', 'retrieved', '8CEC539D9F3E738A277112CE34124ACF097CD266CEA4B5DEDDD928219CAB99EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
