VALUES ('doc-09-mitre-attack-p0-22038', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ComRAT](https://attack.mitre.org/software/S0126) samples have been seen which hijack COM objects for persistence by replacing the path to shell32.dll in registry location HKCU\\Software\\Classes\\CLSID\\{42aedc87-2188-41fd-b9a3-0c966feabec1}\\InprocServer32 .(Citation: NorthSec 2015 GData Uroburos Tools)", "external_references": [{"description": "Rascagneres, P. (2015, May). Tools used by the Uroburos actors. Retrieved August 18, 2016.", "source_name": "NorthSec 2015 GData Uroburos Tools", "url": "https://docplayer.net/101655589-Tools-used-by-the-uroburos-actors.html"}], "id": "relationship--64309b21-2dc2-4369-9c70-66f47f5c4b56", "modified": "2026-04-29T14:23:06.061Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--da5880b4-f7da-4869-85f2-e0aba84b8565", "spec_version": "2.1", "target_ref": "attack-pattern--bc0f5e80-91c0-4e04-9fbb-e4e332c85dae", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22038', 0, 80, '09-mitre-attack', 'retrieved', '2B740B4F6EFE304B5B77B21559AE669A350E776B73F74A19301374730B6F75A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
