VALUES ('doc-09-mitre-attack-p0-22039', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-29T03:41:07.302Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ComRAT](https://attack.mitre.org/software/S0126) has the ability to use the Gmail web UI to receive commands and exfiltrate information.(Citation: ESET ComRAT May 2020)(Citation: CISA ComRAT Oct 2020)", "external_references": [{"description": "Faou, M. (2020, May). From Agent.btz to ComRAT v4: A ten-year journey. Retrieved June 15, 2020.", "source_name": "ESET ComRAT May 2020", "url": "https://www.welivesecurity.com/wp-content/uploads/2020/05/ESET_Turla_ComRAT.pdf"}, {"description": "CISA. (2020, October 29). Malware Analysis Report (AR20-303A). Retrieved December 9, 2020.", "source_name": "CISA ComRAT Oct 2020", "url": "https://us-cert.cisa.gov/ncas/analysis-reports/ar20-303a"}], "id": "relationship--6ff34c78-2c85-4be5-b3db-0ec8543087d9", "modified": "2026-04-29T14:23:06.078Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--da5880b4-f7da-4869-85f2-e0aba84b8565", "spec_version": "2.1", "target_ref": "attack-pattern--be055942-6e63-49d7-9fa1-9cb7d8a8f3f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22039', 0, 98, '09-mitre-attack', 'retrieved', '992912D05908EF84FBAF503722AC189A9BDE813EE89C734FDAA0BCB6398B2004', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
