VALUES ('doc-09-mitre-attack-p0-22067', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T17:23:28.006Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PowerStallion](https://attack.mitre.org/software/S0393) uses Microsoft OneDrive as a C2 server via a network drive mapped with net use .(Citation: ESET Turla PowerShell May 2019)", "external_references": [{"description": "Faou, M. and Dumont R.. (2019, May 29). A dive into Turla PowerShell usage. Retrieved June 14, 2019.", "source_name": "ESET Turla PowerShell May 2019", "url": "https://www.welivesecurity.com/2019/05/29/turla-powershell-usage/"}], "id": "relationship--033a5e59-ab65-485b-a9c0-775977e8abd0", "modified": "2026-04-29T14:23:05.907Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--dcac85c1-6485-4790-84f6-de5e6f6b91dd", "spec_version": "2.1", "target_ref": "attack-pattern--be055942-6e63-49d7-9fa1-9cb7d8a8f3f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22067', 0, 79, '09-mitre-attack', 'retrieved', 'F3F0DD0D400A0BBC283CDB5B2AB22F769037FCF6CC6C82921347A168E8C4F66E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
