VALUES ('doc-09-mitre-attack-p0-22080', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-04T21:29:23.155Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Manjusaka](https://attack.mitre.org/software/S1156) extracts credentials from the Windows Registry associated with Premiumsoft Navicat, a utility used to facilitate access to various database types.(Citation: Talos Manjusaka 2022)", "external_references": [{"description": "Asheer Malhotra & Vitor Ventura. (2022, August 2). Manjusaka: A Chinese sibling of Sliver and Cobalt Strike. Retrieved September 4, 2024.", "source_name": "Talos Manjusaka 2022", "url": "https://blog.talosintelligence.com/manjusaka-offensive-framework/"}], "id": "relationship--2608b224-fb63-4bc6-aa21-ce0537b31861", "modified": "2026-04-29T14:23:05.957Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--dd2ad3d7-d7ef-4af5-a919-bfe8f2571705", "spec_version": "2.1", "target_ref": "attack-pattern--3fc9b85a-2862-4363-a64d-d692e3ffbee0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22080', 0, 82, '09-mitre-attack', 'retrieved', 'BFA489624197C9E26B39AD2F4C5F3E58C20FB3FA7134BE5BFBBB67F71A6742D4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
