VALUES ('doc-09-mitre-attack-p0-22089', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-28T14:07:59.254Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [IceApple](https://attack.mitre.org/software/S1022) [ifconfig](https://attack.mitre.org/software/S0101) module can iterate over all network interfaces on the host and retrieve the name, description, MAC address, DNS suffix, DNS servers, gateways, IPv4 addresses, and subnet masks.(Citation: CrowdStrike IceApple May 2022)", "external_references": [{"description": "CrowdStrike. (2022, May). ICEAPPLE: A NOVEL INTERNET INFORMATION SERVICES (IIS) POST-EXPLOITATION FRAMEWORK. Retrieved June 27, 2022.", "source_name": "CrowdStrike IceApple May 2022", "url": "https://www.crowdstrike.com/wp-content/uploads/2022/05/crowdstrike-iceapple-a-novel-internet-information-services-post-exploitation-framework.pdf"}], "id": "relationship--071f5618-aac7-45ca-9fb5-c863b5d6a179", "modified": "2026-04-29T14:23:05.913Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--dd889a55-fb2c-4ec7-8e9f-c399939a49e1", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22089', 0, 88, '09-mitre-attack', 'retrieved', 'C680934966CCF1E9D64B41B57C6B28B0238685225652A031AA8B4FF5AAE12394', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
