VALUES ('doc-09-mitre-attack-p0-22107', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-26T20:41:04.710Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IceApple](https://attack.mitre.org/software/S1022)''s Credential Dumper module can dump encrypted password hashes from SAM registry keys, including `HKLM\\SAM\\SAM\\Domains\\Account\\F` and `HKLM\\SAM\\SAM\\Domains\\Account\\Users\\*\\V`.(Citation: CrowdStrike IceApple May 2022)", "external_references": [{"description": "CrowdStrike. (2022, May). ICEAPPLE: A NOVEL INTERNET INFORMATION SERVICES (IIS) POST-EXPLOITATION FRAMEWORK. Retrieved June 27, 2022.", "source_name": "CrowdStrike IceApple May 2022", "url": "https://www.crowdstrike.com/wp-content/uploads/2022/05/crowdstrike-iceapple-a-novel-internet-information-services-post-exploitation-framework.pdf"}], "id": "relationship--e4030866-a970-4af5-9d50-b33c7751a8ba", "modified": "2026-04-29T14:23:06.236Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--dd889a55-fb2c-4ec7-8e9f-c399939a49e1", "spec_version": "2.1", "target_ref": "attack-pattern--1644e709-12d2-41e5-a60f-3470991f5011", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22107', 0, 75, '09-mitre-attack', 'retrieved', '00C23188A4D4E054E15789A8A2847E455AA81EDDCAA73382B3DE8D0C3420F1BA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
