VALUES ('doc-09-mitre-attack-p0-22110', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-09T20:43:28.194Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Shai-Hulud](https://attack.mitre.org/software/S9008) has stopped `systemd-resolved` in order to manipulate DNS and firewalls.(Citation: Socket Shai-Hulud November 2025)", "external_references": [{"description": "Socket Research Team. (2025, November 24). Shai Hulud Strikes Again (v2). Retrieved April 9, 2026.", "source_name": "Socket Shai-Hulud November 2025", "url": "https://socket.dev/blog/shai-hulud-strikes-again-v2"}], "id": "relationship--1774b6a5-f9e2-473d-a826-515049e6c774", "modified": "2026-04-29T14:23:05.936Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--de376fb9-1093-4f59-8d13-aed61042701d", "spec_version": "2.1", "target_ref": "attack-pattern--dfefe2ed-4389-4318-8762-f0272b350a1b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22110', 0, 68, '09-mitre-attack', 'retrieved', 'F54D13BC28DA65FFB6EE44EAC9C1544A28617D081F31470B2CE1724BD87AB848', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
