VALUES ('doc-09-mitre-attack-p0-22111', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-09T20:33:38.625Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Shai-Hulud](https://attack.mitre.org/software/S9008) has delayed execution of its larger payloads by forking itself into background process.(Citation: Palo Alto Unit 42 Shai-Hulud November 2025)", "external_references": [{"description": "Justin Moore. (2025, November 25). \"Shai-Hulud\" Worm Compromises npm Ecosystem in Supply Chain Attack (Updated November 26). Retrieved April 9, 2026.", "source_name": "Palo Alto Unit 42 Shai-Hulud November 2025", "url": "https://unit42.paloaltonetworks.com/npm-supply-chain-attack/"}], "id": "relationship--24ccb55f-1e6a-48be-a222-aa0faf1272c3", "modified": "2026-04-29T14:23:05.955Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--de376fb9-1093-4f59-8d13-aed61042701d", "spec_version": "2.1", "target_ref": "attack-pattern--a1df809c-7d0e-459f-8fe5-25474bab770b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22111', 0, 83, '09-mitre-attack', 'retrieved', '6053A6C4B92B43E4FFAD02FCA9C2AAD380B27898F49F2F8F15D17BF5AC67880E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
