VALUES ('doc-09-mitre-attack-p0-22113', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-09T20:28:31.523Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Shai-Hulud](https://attack.mitre.org/software/S9008) has destroyed the victim’s home directory by overwriting and deleting every writable file within the user''s home folder.(Citation: Palo Alto Unit 42 Shai-Hulud November 2025)(Citation: Socket Shai-Hulud November 2025) [Shai-Hulud](https://attack.mitre.org/software/S9008) has also utilized the `shred` command on Linux devices.(Citation: Microsoft Shai-Hulud December 2025)", "external_references": [{"description": "Justin Moore. (2025, November 25). \"Shai-Hulud\" Worm Compromises npm Ecosystem in Supply Chain Attack (Updated November 26). Retrieved April 9, 2026.", "source_name": "Palo Alto Unit 42 Shai-Hulud November 2025", "url": "https://unit42.paloaltonetworks.com/npm-supply-chain-attack/"}, {"description": "Microsoft Defender Security Team. (n.d.). Shai-Hulud 2.0: Guidance for detecting, investigating, and defending against the supply chain attack. Retrieved April 9, 2026.", "source_name": "Microsoft Shai-Hulud December 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/12/09/shai-hulud-2-0-guidance-for-detecting-investigating-and-defending-against-the-supply-chain-attack/"}, {"description": "Socket Research Team. (2025, November 24). Shai Hulud Strikes Again (v2). Retrieved April 9, 2026.", "source_name": "Socket Shai-Hulud November 2025", "url": "https://socket.dev/blog/shai-hulud-strikes-again-v2"}], "id": "relationship--3184811d-4b00-4fdd-aa4b-5c16eb3294ed", "modified": "2026-04-29T14:23:05.981Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--de376fb9-1093-4f59-8d13-aed61042701d", "spec_version": "2.1", "target_ref": "attack-pattern--d45a3d09-b3cf-48f4-9f0f-f521ee5cb05c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22113', 0, 159, '09-mitre-attack', 'retrieved', '37CC142DF906A8457933D80BF55E0794023ACEE424EA664DC9F34F28DEFE1FE3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
