VALUES ('doc-09-mitre-attack-p0-22120', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-09T19:23:50.186Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Shai-Hulud](https://attack.mitre.org/software/S9008) has gathered secrets from AWS Secrets and GCP Secret Manager.(Citation: Aikido Shai-Hulud September 2025)(Citation: Netskope Shai-Hulud November 2025)(Citation: Socket Shai-Hulud November 2025) [Shai-Hulud](https://attack.mitre.org/software/S9008) has also gathered data from Azure Key Vault.(Citation: Netskope Shai-Hulud November 2025)(Citation: Socket Shai-Hulud November 2025)", "external_references": [{"description": "Charlie Eriksen. (2025, September 16). S1ngularity/nx attackers strike again. Retrieved April 9, 2026.", "source_name": "Aikido Shai-Hulud September 2025", "url": "https://www.aikido.dev/blog/s1ngularity-nx-attackers-strike-again"}, {"description": "Gianpietro Cutolo. (2025, November 26). Shai-Hulud 2.0: Aggressive, Automated, and Fast Spreading. Retrieved April 9, 2026.", "source_name": "Netskope Shai-Hulud November 2025", "url": "https://www.netskope.com/blog/shai-hulud-2-0-aggressive-automated-one-of-fastest-spreading-npm-supply-chain-attacks-ever-observed"}, {"description": "Socket Research Team. (2025, November 24). Shai Hulud Strikes Again (v2). Retrieved April 9, 2026.", "source_name": "Socket Shai-Hulud November 2025", "url": "https://socket.dev/blog/shai-hulud-strikes-again-v2"}], "id": "relationship--68929916-ab9f-4078-b959-e500f8cab3b8", "modified": "2026-04-29T14:23:06.067Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--de376fb9-1093-4f59-8d13-aed61042701d", "spec_version": "2.1", "target_ref": "attack-pattern--cfb525cc-5494-401d-a82b-2539ca46a561", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22120', 0, 138, '09-mitre-attack', 'retrieved', '25FA0FC536DAA4E1ED3CB3BACB82396FD74AC2C8346ED17432A44435EB3A336E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
