VALUES ('doc-09-mitre-attack-p0-22121', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-09T21:00:48.106Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Shai-Hulud](https://attack.mitre.org/software/S9008) has suppressed NPM warnings by silently exiting through the use of the NPM success code that has a setting that all errors exit with `code 0`.(Citation: Socket Shai-Hulud November 2025)", "external_references": [{"description": "Socket Research Team. (2025, November 24). Shai Hulud Strikes Again (v2). Retrieved April 9, 2026.", "source_name": "Socket Shai-Hulud November 2025", "url": "https://socket.dev/blog/shai-hulud-strikes-again-v2"}], "id": "relationship--70d9fcbc-3fad-4a6e-a246-e893ee5568a6", "modified": "2026-04-29T14:23:06.079Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--de376fb9-1093-4f59-8d13-aed61042701d", "spec_version": "2.1", "target_ref": "attack-pattern--4a2975db-414e-4c0c-bd92-775987514b4b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22121', 0, 84, '09-mitre-attack', 'retrieved', '69527517C433C10A7034A601CC89F8F2BE31E9B86E8519D46088A5CB9C09B2B1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
