VALUES ('doc-09-mitre-attack-p0-22125', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-09T19:42:20.786Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Shai-Hulud](https://attack.mitre.org/software/S9008) has created a repository named `Shai-Hulud` under the compromised account that commits a JSON dump that contains system information, environment variables and collected secrets.(Citation: Aikido Shai-Hulud September 2025)(Citation: Netskope Shai-Hulud November 2025)(Citation: Wiz Shai-Hulud September 2025) [Shai-Hulud](https://attack.mitre.org/software/S9008) has also posted stolen credentials to public GitHub repositories.(Citation: Palo Alto Unit 42 Shai-Hulud November 2025)(Citation: Microsoft Shai-Hulud December 2025)(Citation: Socket Shai-Hulud November 2025)(Citation: Socket Shai-Hulud Trufflehog September 2025)", "external_references": [{"description": "Charlie Eriksen. (2025, September 16). S1ngularity/nx attackers strike again. Retrieved April 9, 2026.", "source_name": "Aikido Shai-Hulud September 2025", "url": "https://www.aikido.dev/blog/s1ngularity-nx-attackers-strike-again"}, {"description": "Gianpietro Cutolo. (2025, November 26). Shai-Hulud 2.0: Aggressive, Automated, and Fast Spreading. Retrieved April 9, 2026.", "source_name": "Netskope Shai-Hulud November 2025", "url": "https://www.netskope.com/blog/shai-hulud-2-0-aggressive-automated-one-of-fastest-spreading-npm-supply-chain-attacks-ever-observed"}, {"description": "Justin Moore. (2025, November 25). \"Shai-Hulud\" Worm Compromises npm Ecosystem in Supply Chain Attack (Updated November 26). Retrieved April 9, 2026.", "source_name": "Palo Alto Unit 42 Shai-Hulud November 2025", "url": "https://unit42.paloaltonetworks.com/npm-supply-chain-attack/"}, {"description": "Merav Bar, Rami McCarthy, Barak Sharoni. (2025, September 16). Shai-Hulud: Ongoing Package Supply Chain Worm Delivering Data-Stealing Malware. Retrieved April 9, 2026.", "source_name": "Wiz Shai-Hulud September 2025", "url": "https://www.wiz.io/blog/shai-hulud-npm-supply-chain-attack"}, {"description": "Microsoft Defender Security Team. (n.d.). Shai-Hulud 2.0: Guidance for detecting, investigating, and defending against the supply chain attack. Retrieved April 9, 2026.", "source_name": "Microsoft Shai-Hulud December 2025", "url": "https://www.microsoft.com/en-us/security/blog/2025/12/09/shai-hulud-2-0-guidance-for-detecting-investigating-and-defending-against-the-supply-chain-attack/"}, {"description": "Socket Research Team. (2025, November 24). Shai Hulud Strikes Again (v2). Retrieved April 9, 2026.", "source_name": "Socket Shai-Hulud November 2025", "url": "https://socket.dev/blog/shai-hulud-strikes-again-v2"}, {"description": "Socket Research Team. (2025, September 15). Popular Tinycolor npm Package Compromised in Supply Chain Attack Affecting 40+ Packages. Retrieved April 9, 2026.", "source_name": "Socket Shai-Hulud Trufflehog September 2025", "url": "https://socket.dev/blog/tinycolor-supply-chain-attack-affects-40-packages"}], "id": "relationship--8c4a2116-5b4c-4e3a-bace-b59ce29f2246", "modified": "2026-04-29T14:23:06.117Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--de376fb9-1093-4f59-8d13-aed61042701d", "spec_version": "2.1", "target_ref": "attack-pattern--86a96bf6-cf8b-411c-aaeb-8959944d64f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22125', 0, 288, '09-mitre-attack', 'retrieved', 'EFC9A8FBD408D09E06ACF1B6D4CA5A571ABE4F59643295261C81ABB5F7DC2B93', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
