VALUES ('doc-09-mitre-attack-p0-22280', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-30T20:08:11.040Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mis-Type](https://attack.mitre.org/software/S0084) has created registry keys for persistence, including `HKCU\\Software\\bkfouerioyou`, `HKLM\\SOFTWARE\\Microsoft\\Active Setup\\Installed Components\\{6afa8072-b2b1-31a8-b5c1-{Unique Identifier}`, and `HKLM\\SOFTWARE\\Microsoft\\Active Setup\\Installed Components\\{3BF41072-B2B1-31A8-B5C1-{Unique Identifier}`.(Citation: Cylance Dust Storm)", "external_references": [{"description": "Gross, J. (2016, February 23). Operation Dust Storm. Retrieved December 22, 2021.", "source_name": "Cylance Dust Storm", "url": "https://s7d2.scene7.com/is/content/cylance/prod/cylance-web/en-us/resources/knowledge-center/resource-library/reports/Op_Dust_Storm_Report.pdf"}], "id": "relationship--323eed81-9e09-44fb-9dea-bad6aae88e7f", "modified": "2026-04-29T14:23:05.983Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e1161124-f22e-487f-9d5f-ed8efc8dcd61", "spec_version": "2.1", "target_ref": "attack-pattern--1ecb2399-e8ba-4f6b-8ba7-5c27d49405cf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22280', 0, 70, '09-mitre-attack', 'retrieved', 'B631ABE9E83D399F0B61E5C66D8717A89223F8EABD0DA3D957143F236EB161D1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
