VALUES ('doc-09-mitre-attack-p0-22289', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mis-Type](https://attack.mitre.org/software/S0084) may create a file containing the results of the command cmd.exe /c net user {Username} .(Citation: Cylance Dust Storm)", "external_references": [{"description": "Gross, J. (2016, February 23). Operation Dust Storm. Retrieved December 22, 2021.", "source_name": "Cylance Dust Storm", "url": "https://s7d2.scene7.com/is/content/cylance/prod/cylance-web/en-us/resources/knowledge-center/resource-library/reports/Op_Dust_Storm_Report.pdf"}], "id": "relationship--a33c172b-9910-4f36-8373-32126201144b", "modified": "2026-04-29T14:23:06.147Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e1161124-f22e-487f-9d5f-ed8efc8dcd61", "spec_version": "2.1", "target_ref": "attack-pattern--25659dd6-ea12-45c4-97e6-381e3e4b593e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22289', 0, 69, '09-mitre-attack', 'retrieved', '29EBDB3A45EB4AB4BF0ACC7203671A0F682C399FC11891416CD90384839C581B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
