VALUES ('doc-09-mitre-attack-p0-22295', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-30T20:21:03.201Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mis-Type](https://attack.mitre.org/software/S0084) has been injected directly into a running process, including `explorer.exe`.(Citation: Cylance Dust Storm)", "external_references": [{"description": "Gross, J. (2016, February 23). Operation Dust Storm. Retrieved December 22, 2021.", "source_name": "Cylance Dust Storm", "url": "https://s7d2.scene7.com/is/content/cylance/prod/cylance-web/en-us/resources/knowledge-center/resource-library/reports/Op_Dust_Storm_Report.pdf"}], "id": "relationship--d83274f8-ac2b-4416-9fae-97f569dbcef2", "modified": "2026-04-29T14:23:06.220Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e1161124-f22e-487f-9d5f-ed8efc8dcd61", "spec_version": "2.1", "target_ref": "attack-pattern--43e7dc91-05b2-474c-b9ac-2ed4fe101f4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22295', 0, 63, '09-mitre-attack', 'retrieved', '3FB1AC84A19FBA6E1992765DDF30C4E278B70FF659E05151BEB6DA6B37FFA992', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
