VALUES ('doc-09-mitre-attack-p0-22297', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-01T21:09:19.067Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LunarWeb](https://attack.mitre.org/software/S1141) can capture information on group policy settings(Citation: ESET Turla Lunar toolset May 2024)", "external_references": [{"description": "Jurčacko, F. (2024, May 15). To the Moon and back(doors): Lunar landing in diplomatic missions. Retrieved June 26, 2024.", "source_name": "ESET Turla Lunar toolset May 2024", "url": "https://www.welivesecurity.com/en/eset-research/moon-backdoors-lunar-landing-diplomatic-missions/"}], "id": "relationship--01b475dc-8b42-4cc1-a88b-6081cbc54efd", "modified": "2026-04-29T14:23:05.905Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e1284931-3f85-4262-a641-9ae8bb0576a0", "spec_version": "2.1", "target_ref": "attack-pattern--1b20efbf-8063-4fc3-a07d-b575318a301b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22297', 0, 73, '09-mitre-attack', 'retrieved', '36AC5BC605E162D51D79744BFB4812E5740C876771609A5080C882FC0AA5C019', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
