VALUES ('doc-09-mitre-attack-p0-22298', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-01T20:45:59.774Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LunarWeb](https://attack.mitre.org/software/S1141) can run shell commands using a BAT file with a name matching `%TEMP%\\ .batfile` or through cmd.exe with the `/c` and `/U` option for Unicode output.(Citation: ESET Turla Lunar toolset May 2024)", "external_references": [{"description": "Jurčacko, F. (2024, May 15). To the Moon and back(doors): Lunar landing in diplomatic missions. Retrieved June 26, 2024.", "source_name": "ESET Turla Lunar toolset May 2024", "url": "https://www.welivesecurity.com/en/eset-research/moon-backdoors-lunar-landing-diplomatic-missions/"}], "id": "relationship--08bf9136-b5a3-4f46-893a-3bd4f7911f91", "modified": "2026-04-29T14:23:05.915Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e1284931-3f85-4262-a641-9ae8bb0576a0", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22298', 0, 92, '09-mitre-attack', 'retrieved', '6F1EC47C6806E4D0B78C34A882A993D57F8CE0D5E5AC18828AC97CFDAA52CBFA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
