VALUES ('doc-09-mitre-attack-p0-22326', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-07T21:28:23.913Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XCSSET](https://attack.mitre.org/software/S0658) uses a hidden folder named .xcassets and .git to embed itself in Xcode.(Citation: trendmicro xcsset xcode project 2020)", "external_references": [{"description": "Mac Threat Response, Mobile Research Team. (2020, August 13). The XCSSET Malware: Inserts Malicious Code Into Xcode Projects, Performs UXSS Backdoor Planting in Safari, and Leverages Two Zero-day Exploits. Retrieved October 5, 2021.", "source_name": "trendmicro xcsset xcode project 2020", "url": "https://documents.trendmicro.com/assets/pdf/XCSSET_Technical_Brief.pdf"}], "id": "relationship--05ee3203-83ad-4dd3-8590-b7f3ffcf772a", "modified": "2026-04-29T14:23:05.911Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e14085cb-0e8d-4be6-92ba-e3b93ee5978f", "spec_version": "2.1", "target_ref": "attack-pattern--ec8fc7e2-b356-455c-8db5-2e37be158e7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22326', 0, 91, '09-mitre-attack', 'retrieved', '7A47258BADACA45C789D8E4D2185ECADA6A6334D31CE095E4D4B4AF5245B0E4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
