VALUES ('doc-09-mitre-attack-p0-22331', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-04T04:29:43.463Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XCSSET](https://attack.mitre.org/software/S0658) has dropped a malicious applet into an app''s `.../Contents/MacOS/` folder of a previously launched app to bypass Gatekeeper''s security checks on first launch apps (prior to macOS 13).(Citation: Application Bundle Manipulation Brandon Dalton)", "external_references": [{"description": "Brandon Dalton. (2022, August 9). A bundle of nerves: Tweaking macOS security controls to thwart application bundle manipulation. Retrieved September 27, 2022.", "source_name": "Application Bundle Manipulation Brandon Dalton", "url": "https://redcanary.com/blog/mac-application-bundles/"}], "id": "relationship--3a72e519-b85c-4dec-9ffd-74eec8af03ca", "modified": "2026-04-29T14:23:06.001Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e14085cb-0e8d-4be6-92ba-e3b93ee5978f", "spec_version": "2.1", "target_ref": "attack-pattern--31a0a2ac-c67c-4a7e-b9ed-6a96477d4e8e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22331', 0, 95, '09-mitre-attack', 'retrieved', 'A3B3FB728D63043DA20B7409727679E04F2F00972CFA1CB8332EA81307A8A6C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
