VALUES ('doc-09-mitre-attack-p0-22339', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-04-02T19:45:35.768Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For several modules, [XCSSET](https://attack.mitre.org/software/S0658) attempts to access or list the contents of user folders such as Desktop, Downloads, and Documents. If the folder does not exist or access is denied, it enters a loop where it resets the TCC database and retries access.(Citation: Microsoft March 2025 XCSSET)", "external_references": [{"description": "Microsoft Threat Intelligence. (2025, March 11). New XCSSET malware adds new obfuscation, persistence techniques to infect Xcode projects. Retrieved April 2, 2025.", "source_name": "Microsoft March 2025 XCSSET", "url": "https://www.microsoft.com/en-us/security/blog/2025/03/11/new-xcsset-malware-adds-new-obfuscation-persistence-techniques-to-infect-xcode-projects/"}], "id": "relationship--83116ad2-7302-4c5b-9a43-5a32c5bd2c32", "modified": "2026-04-29T14:23:06.105Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e14085cb-0e8d-4be6-92ba-e3b93ee5978f", "spec_version": "2.1", "target_ref": "attack-pattern--e8a0a025-3601-4755-abfb-8d08283329fb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22339', 0, 107, '09-mitre-attack', 'retrieved', '62038942AAB7903DA21EF5D33F0159E6975C6343FAFCDFE3E1FE4760135B2EA1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
