VALUES ('doc-09-mitre-attack-p0-22344', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-07T21:28:23.985Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XCSSET](https://attack.mitre.org/software/S0658) loads a system level launchdaemon using the launchctl load -w command from /System/Librarby/LaunchDaemons/ssh.plist .(Citation: trendmicro xcsset xcode project 2020)", "external_references": [{"description": "Mac Threat Response, Mobile Research Team. (2020, August 13). The XCSSET Malware: Inserts Malicious Code Into Xcode Projects, Performs UXSS Backdoor Planting in Safari, and Leverages Two Zero-day Exploits. Retrieved October 5, 2021.", "source_name": "trendmicro xcsset xcode project 2020", "url": "https://documents.trendmicro.com/assets/pdf/XCSSET_Technical_Brief.pdf"}], "id": "relationship--b502aff3-128e-4715-a8bc-7b7b8fa0be74", "modified": "2026-04-29T14:23:06.172Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e14085cb-0e8d-4be6-92ba-e3b93ee5978f", "spec_version": "2.1", "target_ref": "attack-pattern--810aa4ad-61c9-49cb-993f-daa06199421d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22344', 0, 92, '09-mitre-attack', 'retrieved', 'D01823E316A71FB6767F813297814DDA59B87FABFAFB32B7203DE612DA3C81BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
