VALUES ('doc-09-mitre-attack-p0-22348', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-07T21:28:23.912Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XCSSET](https://attack.mitre.org/software/S0658) uses the ssh launchdaemon to elevate privileges, bypass system controls, and enable remote access to the victim.(Citation: trendmicro xcsset xcode project 2020)", "external_references": [{"description": "Mac Threat Response, Mobile Research Team. (2020, August 13). The XCSSET Malware: Inserts Malicious Code Into Xcode Projects, Performs UXSS Backdoor Planting in Safari, and Leverages Two Zero-day Exploits. Retrieved October 5, 2021.", "source_name": "trendmicro xcsset xcode project 2020", "url": "https://documents.trendmicro.com/assets/pdf/XCSSET_Technical_Brief.pdf"}], "id": "relationship--ce0e6abe-ebdb-45f4-a403-261587e0fa0f", "modified": "2026-04-29T14:23:06.207Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e14085cb-0e8d-4be6-92ba-e3b93ee5978f", "spec_version": "2.1", "target_ref": "attack-pattern--573ad264-1371-4ae0-8482-d2673b719dba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22348', 0, 95, '09-mitre-attack', 'retrieved', 'D2DDB9F84A01BABD057856CB3252E5F6F6EDE2D79764E11737BC858F0ACC369B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
