INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-22349', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-11T16:22:51.765Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In older versions, [XCSSET](https://attack.mitre.org/software/S0658) uses the plutil command to modify the LSUIElement , DFBundleDisplayName , and CFBundleIdentifier keys in the /Contents/Info.plist file to change how [XCSSET](https://attack.mitre.org/software/S0658) is visible on the system. In later versions, [XCSSET](https://attack.mitre.org/software/S0658) leverages a third-party notarized `dockutil` tool to modify the `.plist` file responsible for presenting applications to the user in the Dock and LaunchPad to point to a malicious application.(Citation: trendmicro xcsset xcode project 2020)(Citation: Microsoft March 2025 XCSSET)", "external_references": [{"description": "Mac Threat Response, Mobile Research Team. (2020, August 13). The XCSSET Malware: Inserts Malicious Code Into Xcode Projects, Performs UXSS Backdoor Planting in Safari, and Leverages Two Zero-day Exploits. Retrieved October 5, 2021.", "source_name": "trendmicro xcsset xcode project 2020", "url": "https://documents.trendmicro.com/assets/pdf/XCSSET_Technical_Brief.pdf"}, {"description": "Microsoft Threat Intelligence. (2025, March 11). New XCSSET malware adds new obfuscation, persistence techniques to infect Xcode projects. Retrieved April 2, 2025.", "source_name": "Microsoft March 2025 XCSSET", "url": "https://www.microsoft.com/en-us/security/blog/2025/03/11/new-xcsset-malware-adds-new-obfuscation-persistence-techniques-to-infect-xcode-projects/"}], "id": "relationship--d4992852-13b0-4bfb-aee3-09d658a52785", "modified": "2026-04-29T14:23:06.216Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e14085cb-0e8d-4be6-92ba-e3b93ee5978f", "spec_version": "2.1", "target_ref": "attack-pattern--7d20fff9-8751-404e-badd-ccd71bda0236", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22349', 0, 175, '09-mitre-attack', 'retrieved', 'CAC0DB1E9A82B036F41288404426DE57C001CA52333829D86D4477A9F7F2CB76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
