VALUES ('doc-09-mitre-attack-p0-22355', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-07T21:28:23.946Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[XCSSET](https://attack.mitre.org/software/S0658) attempts to discover accounts from various locations such as a user''s Evernote, AppleID, Telegram, Skype, and WeChat data.(Citation: trendmicro xcsset xcode project 2020)", "external_references": [{"description": "Mac Threat Response, Mobile Research Team. (2020, August 13). The XCSSET Malware: Inserts Malicious Code Into Xcode Projects, Performs UXSS Backdoor Planting in Safari, and Leverages Two Zero-day Exploits. Retrieved October 5, 2021.", "source_name": "trendmicro xcsset xcode project 2020", "url": "https://documents.trendmicro.com/assets/pdf/XCSSET_Technical_Brief.pdf"}], "id": "relationship--e481bd6a-3143-4fd6-b1d9-97d1060f423d", "modified": "2026-04-29T14:23:06.236Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e14085cb-0e8d-4be6-92ba-e3b93ee5978f", "spec_version": "2.1", "target_ref": "attack-pattern--72b74d71-8169-42aa-92e0-e7b04b9f5a08", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22355', 0, 96, '09-mitre-attack', 'retrieved', 'AB87CBB90240C1686AAA22331D3F2516867F976E10761E45D43A35E8E95EE6C2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
