VALUES ('doc-09-mitre-attack-p0-22400', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-20T18:10:33.808Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KillDisk](https://attack.mitre.org/software/S0607) has a ransomware component that encrypts files with an AES key that is also RSA-1028 encrypted.(Citation: KillDisk Ransomware)", "external_references": [{"description": "Catalin Cimpanu. (2016, December 29). KillDisk Disk-Wiping Malware Adds Ransomware Component. Retrieved January 12, 2021.", "source_name": "KillDisk Ransomware", "url": "https://www.bleepingcomputer.com/news/security/killdisk-disk-wiping-malware-adds-ransomware-component/"}], "id": "relationship--c6cfaa54-2ce3-40c8-af91-cd09e6e9c167", "modified": "2026-04-29T14:23:06.197Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e221eb77-1502-4129-af1d-fe1ad55e7ec6", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22400', 0, 70, '09-mitre-attack', 'retrieved', 'C7F79C4D732179ADB94DF2326CD31DB13C834A77F844E9D35BF8D78E0E6B4AF5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
