VALUES ('doc-09-mitre-attack-p0-22401', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-01-31T19:52:29.757Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KillDisk](https://attack.mitre.org/software/S0607) has the ability to quit and delete itself.(Citation: ESET Telebots Dec 2016)", "external_references": [{"description": "Cherepanov, A.. (2016, December 13). The rise of TeleBots: Analyzing disruptive KillDisk attacks. Retrieved June 10, 2020.", "source_name": "ESET Telebots Dec 2016", "url": "https://www.welivesecurity.com/2016/12/13/rise-telebots-analyzing-disruptive-killdisk-attacks/"}], "id": "relationship--c86a1525-d555-4467-8d1c-1f8b0c277d1c", "modified": "2026-04-29T14:23:06.199Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e221eb77-1502-4129-af1d-fe1ad55e7ec6", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22401', 0, 68, '09-mitre-attack', 'retrieved', 'EC74C635B796C1ABF1C5C71F47AF7FA53F3D8D68A971CA1ED74F7E00FB0628F6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
