VALUES ('doc-09-mitre-attack-p0-22403', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-13T21:34:46.654Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KillDisk](https://attack.mitre.org/software/S0607) has attempted to get the access token of a process by calling OpenProcessToken . If [KillDisk](https://attack.mitre.org/software/S0607) gets the access token, then it attempt to modify the token privileges with AdjustTokenPrivileges .(Citation: Trend Micro KillDisk 2)", "external_references": [{"description": "Gilbert Sison, Rheniel Ramos, Jay Yaneza, Alfredo Oliveira. (2018, January 15). KillDisk Variant Hits Latin American Financial Groups. Retrieved January 12, 2021.", "source_name": "Trend Micro KillDisk 2", "url": "https://www.trendmicro.com/en_us/research/18/a/new-killdisk-variant-hits-financial-organizations-in-latin-america.html"}], "id": "relationship--d84bda97-a8d5-4886-8172-c5a794b681af", "modified": "2026-04-29T14:23:06.220Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e221eb77-1502-4129-af1d-fe1ad55e7ec6", "spec_version": "2.1", "target_ref": "attack-pattern--dcaa092b-7de9-4a21-977f-7fcb77e89c48", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22403', 0, 96, '09-mitre-attack', 'retrieved', 'FAB8747112A617CC3E1274C49266566BFFB46C1459C6D9196EAEE4D989071602', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
