VALUES ('doc-09-mitre-attack-p0-22405', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-30T15:26:07.940Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) can employ several code obfuscation methods, including renaming functions, altering control flows, and encrypting strings.(Citation: HC3 Qilin Threat Profile JUN 2024)", "external_references": [{"description": "Health Sector Cybersecurity Coordination Center. (2024, June 18). Qilin, aka Agenda Ransomware. Retrieved September 26, 2025.", "source_name": "HC3 Qilin Threat Profile JUN 2024", "url": "https://www.aha.org/system/files/media/file/2024/06/tlp-clear-hc3-threat-profile-qilin-aka-agenda-ransomware-6-18-2024.pdf"}], "id": "relationship--0059d5e7-7a7f-4a13-8730-00383bad2e98", "modified": "2026-04-29T14:23:05.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22405', 0, 78, '09-mitre-attack', 'retrieved', '37527DAC87AC3AEF55118EAEDED2267DD4778396C043D4EDF221BC065705D442', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
