VALUES ('doc-09-mitre-attack-p0-22407', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-30T15:49:09.189Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) can use an embedded [Mimikatz](https://attack.mitre.org/software/S0002) module for token manipulation.(Citation: Picus Qilin MAR 2025)", "external_references": [{"description": "Hacioglu, S. (2025, March 10). Qilin Ransomware: Exposing the TTPs Behind One of the Most Active Ransomware Campaigns of 2024. Retrieved September 26, 2025.", "source_name": "Picus Qilin MAR 2025", "url": "https://www.picussecurity.com/resource/blog/qilin-ransomware"}], "id": "relationship--0a068599-574d-4df3-8b05-6194e7366cc4", "modified": "2026-04-29T14:23:05.917Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--dcaa092b-7de9-4a21-977f-7fcb77e89c48", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22407', 0, 76, '09-mitre-attack', 'retrieved', 'A4083A10FDEAA4CB890AE402A2A7994A63601A62EE1EC417D026CDB0FD168FAF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
