VALUES ('doc-09-mitre-attack-p0-22420', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-30T15:47:50.866Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) can require a specific password to be passed by command-line argument during execution which must match a pre-defined value in the configuration in order for it to continue execution.(Citation: Picus Qilin MAR 2025)(Citation: Trend Micro Agenda Ransomware OCT 2025)", "external_references": [{"description": "Hacioglu, S. (2025, March 10). Qilin Ransomware: Exposing the TTPs Behind One of the Most Active Ransomware Campaigns of 2024. Retrieved September 26, 2025.", "source_name": "Picus Qilin MAR 2025", "url": "https://www.picussecurity.com/resource/blog/qilin-ransomware"}, {"description": "Trend Micro. (2025, October 23). Agenda Ransomware Deploys Linux Variant on Windows Systems Through Remote Management Tools and BYOVD Techniques. Retrieved March 26, 2026.", "source_name": "Trend Micro Agenda Ransomware OCT 2025", "url": "https://www.trendmicro.com/en_us/research/25/j/agenda-ransomware-deploys-linux-variant-on-windows-systems.html"}], "id": "relationship--5c39581b-cf62-4b14-bce2-9efbcf46440b", "modified": "2026-04-29T14:23:06.051Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22420', 0, 136, '09-mitre-attack', 'retrieved', 'F23E95A9E1E19CBF4EEFC2FB72D961A2D7199590042D2523029DFCF7D9986934', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "