VALUES ('doc-09-mitre-attack-p0-22421', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-30T18:03:06.394Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) can embed a copy of [PsExec](https://attack.mitre.org/software/S0029) within its payload and place it in the %Temp% directory under a randomly generated filename.(Citation: Picus Qilin MAR 2025)(Citation: Cisco Talos Qilin Ransomware OCT 2025)", "external_references": [{"description": "Hacioglu, S. (2025, March 10). Qilin Ransomware: Exposing the TTPs Behind One of the Most Active Ransomware Campaigns of 2024. Retrieved September 26, 2025.", "source_name": "Picus Qilin MAR 2025", "url": "https://www.picussecurity.com/resource/blog/qilin-ransomware"}, {"description": "Takeda, T. et al. (2025, October 26). Uncovering Qilin attack methods exposed through multiple cases. Retrieved March 26, 2026.", "source_name": "Cisco Talos Qilin Ransomware OCT 2025", "url": "https://blog.talosintelligence.com/uncovering-qilin-attack-methods-exposed-through-multiple-cases/"}], "id": "relationship--602d3c1d-6337-4134-9dc7-b1452f95b88f", "modified": "2026-04-29T14:23:06.056Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--4f9ca633-15c5-463c-9724-bdcd54fde541", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22421', 0, 123, '09-mitre-attack', 'retrieved', '3AC5F55F3A89363127C1AFFC021F4EDF249ED89A105894CBCE5655F7925E5FC8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
