VALUES ('doc-09-mitre-attack-p0-22424', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-29T21:10:27.964Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) has pushed scheduled tasks via Group Policy Objects (GPOs) for execution.(Citation: BushidoToken Qilin RaaS JUN 2024)(Citation: Trend Micro Agenda Ransomware AUG 2022) [Qilin](https://attack.mitre.org/software/S1242) has also created a scheduled task named TVInstallRestore, configured to run at logon using the `/SC ONLOGON` argument.(Citation: Cisco Talos Qilin Ransomware OCT 2025)\n", "external_references": [{"description": "Magdy, S. et al. (2022, August 25). New Golang Ransomware Agenda Customizes Attacks. Retrieved September 26, 2025.", "source_name": "Trend Micro Agenda Ransomware AUG 2022", "url": "https://www.trendmicro.com/en_us/research/22/h/new-golang-ransomware-agenda-customizes-attacks.html"}, {"description": "Takeda, T. et al. (2025, October 26). Uncovering Qilin attack methods exposed through multiple cases. Retrieved March 26, 2026.", "source_name": "Cisco Talos Qilin Ransomware OCT 2025", "url": "https://blog.talosintelligence.com/uncovering-qilin-attack-methods-exposed-through-multiple-cases/"}, {"description": "Thomas, W. (2024, June 12). Tracking Adversaries: The Qilin RaaS. Retrieved September 26, 2025.", "source_name": "BushidoToken Qilin RaaS JUN 2024", "url": "https://blog.bushidotoken.net/2024/06/tracking-adversaries-qilin-raas.html"}], "id": "relationship--6b0992a5-5800-44b2-906b-23d9a7985d22", "modified": "2026-04-29T14:23:06.071Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22424', 0, 157, '09-mitre-attack', 'retrieved', 'E528365A8A658E7762AEA54B2778CA4E24B27E452CB088751E165B9FB24E0A17', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
