VALUES ('doc-09-mitre-attack-p0-22425', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-30T15:13:52.515Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) can make Registry modifications to share networked drives between elevated and non-elevated processes and to increase the number of outstanding network requests per client.(Citation: Halcyon Qilin.B OCT 2024)(Citation: Picus Qilin MAR 2025) [Qilin](https://attack.mitre.org/software/S1242) can also modify `HKEY_CURRENT_USER\\Control Panel\\Desktop\\Wallpaper` to enable posting of ransom messages.(Citation: Cisco Talos Qilin Ransomware OCT 2025)\n", "external_references": [{"description": "Hacioglu, S. (2025, March 10). Qilin Ransomware: Exposing the TTPs Behind One of the Most Active Ransomware Campaigns of 2024. Retrieved September 26, 2025.", "source_name": "Picus Qilin MAR 2025", "url": "https://www.picussecurity.com/resource/blog/qilin-ransomware"}, {"description": "Halcyon RISE Team. (2024, October 24). New Qilin.B Ransomware Variant Boasts Enhanced Encryption and Defense Evasion. Retrieved September 26, 2025.", "source_name": "Halcyon Qilin.B OCT 2024", "url": "https://www.halcyon.ai/blog/new-qilin-b-ransomware-variant-boasts-enhanced-encryption-and-defense-evasion"}, {"description": "Takeda, T. et al. (2025, October 26). Uncovering Qilin attack methods exposed through multiple cases. Retrieved March 26, 2026.", "source_name": "Cisco Talos Qilin Ransomware OCT 2025", "url": "https://blog.talosintelligence.com/uncovering-qilin-attack-methods-exposed-through-multiple-cases/"}], "id": "relationship--6bbefe61-008f-4298-8a9b-364c51ba7c20", "modified": "2026-04-29T14:23:06.072Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22425', 0, 170, '09-mitre-attack', 'retrieved', 'C9E84A8D6306DD912BDACA171AF28483437E0A65EB4CFF070EBBEFE41779EC72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
