VALUES ('doc-09-mitre-attack-p0-22426', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-29T18:52:37.505Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) has the ability to list network drives.(Citation: Trend Micro Agenda Ransomware AUG 2022)(Citation: Halcyon Qilin.B OCT 2024)", "external_references": [{"description": "Halcyon RISE Team. (2024, October 24). New Qilin.B Ransomware Variant Boasts Enhanced Encryption and Defense Evasion. Retrieved September 26, 2025.", "source_name": "Halcyon Qilin.B OCT 2024", "url": "https://www.halcyon.ai/blog/new-qilin-b-ransomware-variant-boasts-enhanced-encryption-and-defense-evasion"}, {"description": "Magdy, S. et al. (2022, August 25). New Golang Ransomware Agenda Customizes Attacks. Retrieved September 26, 2025.", "source_name": "Trend Micro Agenda Ransomware AUG 2022", "url": "https://www.trendmicro.com/en_us/research/22/h/new-golang-ransomware-agenda-customizes-attacks.html"}], "id": "relationship--6e1fe223-d295-4784-b64a-2e2b6586b782", "modified": "2026-04-29T14:23:06.075Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--3489cfc5-640f-4bb3-a103-9137b97de79f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22426', 0, 103, '09-mitre-attack', 'retrieved', '5E25FF52BD82715422A56261AAA830987031A628C34BE8D17A1864A3AC38195C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
