VALUES ('doc-09-mitre-attack-p0-22427', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-29T21:23:34.706Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) has the ability to clear Windows Event Logs.(Citation: Halcyon Qilin.B OCT 2024)(Citation: Sophos Qilin MSP APR 2025)", "external_references": [{"description": "Bradshaw, A. et al. (2025, April 1). Qilin affiliates spear-phish MSP ScreenConnect admin, targeting customers downstream. Retrieved September 26, 2025.", "source_name": "Sophos Qilin MSP APR 2025", "url": "https://news.sophos.com/en-us/2025/04/01/sophos-mdr-tracks-ongoing-campaign-by-qilin-affiliates-targeting-screenconnect/"}, {"description": "Halcyon RISE Team. (2024, October 24). New Qilin.B Ransomware Variant Boasts Enhanced Encryption and Defense Evasion. Retrieved September 26, 2025.", "source_name": "Halcyon Qilin.B OCT 2024", "url": "https://www.halcyon.ai/blog/new-qilin-b-ransomware-variant-boasts-enhanced-encryption-and-defense-evasion"}], "id": "relationship--6eb9c742-7eab-4eef-9036-d9af96dbafb4", "modified": "2026-04-29T14:23:06.076Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--75b9a4d2-d4e2-4ca1-9aab-1badd9e05fd0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22427', 0, 105, '09-mitre-attack', 'retrieved', 'BB67449849815363EFDE1824B0B7811A2BBB7A65F3669A02E242B2890C825EEF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
