VALUES ('doc-09-mitre-attack-p0-22431', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-09T19:10:39.912Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Qilin](https://attack.mitre.org/software/S1242) has run `cmd /C [PsExec] -accepteula \\\\IP Address -c -f -h -d -i\nC:\\Users\\xxx\\ .exe --password [PASSWORD] --spread --spread-process` to execute its encryptor to target multiple network shares.(Citation: Cisco Talos Qilin Ransomware OCT 2025)", "external_references": [{"description": "Takeda, T. et al. (2025, October 26). Uncovering Qilin attack methods exposed through multiple cases. Retrieved March 26, 2026.", "source_name": "Cisco Talos Qilin Ransomware OCT 2025", "url": "https://blog.talosintelligence.com/uncovering-qilin-attack-methods-exposed-through-multiple-cases/"}], "id": "relationship--76f5cf4b-15c0-4aa5-b129-68b3b248e90d", "modified": "2026-04-29T14:23:06.088Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--e23d2777-b85d-44fc-861e-9149d399fbb9", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-22431', 0, 93, '09-mitre-attack', 'retrieved', '2E463A27AC78E404DA1A5BF9E52E90184A97302C71CB72D703B407708F36A52B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
